import Foundation

/// Make Vertical's summary (spec §11 VR-35) and its answer (VR-36): what `plan` did, said as
/// the sheet's and the tool's text and as `make_vertical_version`'s keys. A pure move out of
/// `VerticalVersion+Plan.swift` (road map "creator-jobs" VR5b's toll). Names no `rc_*`.
extension VerticalVersion {
    /// VR-35: the counts, then one line per re-laid switch (VR-54), then one line per entry
    /// with a reason; the graphic counts and lines VR4b's (`templates`, VR-44 (d)).
    static func summary(_ plan: Plan, templates: TemplateReport = TemplateReport()) -> String {
        func count(_ treatment: Treatment) -> Int {
            plan.entries.filter { $0.treatment == treatment }.count
        }
        var text = "Makes a \(plan.width) × \(plan.height) version."
        let followed = count(.followed)
        if followed > 0 { text += " Follows \(counted(followed, "clip"))." }
        if !plan.cursor.isEmpty {
            text += " Follows the cursor in \(counted(plan.cursor.count, "clip")), their own "
                + "zooms and pans replaced."
        }
        if !plan.speaker.isEmpty {
            text += " Follows whoever is talking in \(counted(plan.speaker.count, "clip"))."
        }
        if !plan.relaid.isEmpty {
            text += " Re-lays \(counted(plan.relaid.count, "camera layout")) for the new canvas."
        }
        let whole = count(.whole)
        if whole > 0 { text += " Shows \(counted(whole, "clip")) whole on a blurred copy." }
        let kept = count(.kept)
        if kept > 0 { text += " Keeps \(counted(kept, "clip")) as placed." }
        let refilled = count(.refilled)
        if refilled > 0 { text += " Re-fills \(counted(refilled, "background"))." }
        let removed = count(.removed)
        if removed > 0 {
            text += " Removes \(removed) blurred \(removed == 1 ? "copy" : "copies") the "
                + "framing replaces."
        }
        text += graphicsCounts(plan, templates)
        if plan.backgrounds { text += " Adds a Backgrounds track for the blurred copy." }
        if plan.moreTracks > 0 {
            text += " Adds \(plan.moreTracks) more \(plan.moreTracks == 1 ? "track" : "tracks")"
                + " behind it where clips overlap."
        }
        if plan.reEased > 0 { text += " \(counted(plan.reEased, "action")) re-eased at a cut." }
        if plan.carried > 0 {
            text += " \(counted(plan.carried, "action")) "
                + (plan.carried == 1 ? "carries" : "carry") + " a framing move."
        }
        if let relaid = plan.captions?.relaid.count, relaid > 0 {
            text += " Re-lays \(counted(relaid, "caption track")) for the new canvas."
        }
        let canvas = plan.project.snapshot.canvas
        var lines = [text] + plan.relaid.map { relaidLine($0, canvas: canvas) }
        for entry in plan.entries {
            guard let reason = entry.reason else { continue }
            let why = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
            switch entry.treatment {
            case .notFollowed: lines.append("Clip \(entry.clip) is not followed: \(why).")
            default: lines.append("Clip \(entry.clip) is followed, but \(why).")
            }
        }
        lines += (plan.captions?.kept ?? []).map(CaptionRelayout.keptLine)
        lines += graphicsLines(templates)
        return lines.joined(separator: "\n")
    }

    /// VR-39 (d)'s pending summary, while the analysis is still to be made; with `speaker` it
    /// says the sheet comes back to confirm the microphones' faces (VR-66 (e)).
    static func pendingSummary(files: Int, width: Int, height: Int, speaker: Bool = false)
        -> String
    {
        "Finds the faces, people and shot changes in \(counted(files, "file")) on this Mac "
            + "first, " + (speaker ? "then asks you to confirm who is on each microphone, " : "")
            + "then makes a \(width) × \(height) version."
    }

    /// The answer's keys every door shares (VR-36): `canvas`, `clips` in id order,
    /// `backgrounds`, `more_tracks`, `re_eased`, `moves_carried`, `summary`, `graphics`,
    /// `cursor` (VR-52), `relaid` (VR-54) and `speaker` (VR-64 (f)).
    static func answerFields(_ plan: Plan, templates: TemplateReport = TemplateReport())
        -> [String: Any]
    {
        let clips: [[String: Any]] = plan.entries.map { entry in
            var row: [String: Any] = [
                "clip": Int(entry.clip), "treatment": entry.treatment.rawValue,
            ]
            if let reason = entry.reason { row["reason"] = reason }
            return row
        }
        var fields: [String: Any] = [
            "canvas": ["width": plan.width, "height": plan.height],
            "clips": clips,
            "backgrounds": plan.backgrounds,
            "more_tracks": plan.moreTracks,
            "re_eased": plan.reEased,
            "moves_carried": plan.carried,
            "summary": summary(plan, templates: templates),
            "cursor": plan.cursor.map { Int($0) },
            "relaid": relaidFields(plan.relaid),
            "speaker": plan.speaker.map { framed -> [String: Any] in
                [
                    "clip": Int(framed.clip), "mics": framed.mics.map { Int($0) },
                    "mic_faces": framed.faces.map { Int($0) },
                ]
            },
            "graphics": graphicsFields(plan, templates),
        ]
        if let captions = plan.captions {
            fields["captions"] = CaptionRelayout.answerFields(captions)
        }
        return fields
    }

    static func counted(_ n: Int, _ noun: String) -> String {
        "\(n) \(noun)\(n == 1 ? "" : "s")"
    }
}
import AppKit

/// File ▸ Make Vertical Version… (road map "creator-jobs" VR3b, spec §11 VR-39) — the menu door
/// over VR3a's step (`VerticalVersion.plan`) and copy (`ProjectDocument.verticalCopy`): the
/// sheet (`VerticalVersionSheetController`), and its hand-off — the Analyzing sheet when an
/// analysis is missing, then the copy opened in front or the step applied in place as one undo
/// step "Make Vertical". `make_vertical_version` is the mirror (`AgentServer+VerticalVersion.swift`).
///
/// The sheet never edits. Its hand-off is not an AppKit event, so the step in place goes through
/// `performGroupedEdit` (Follow Subject's shape), and only onto the project handle and scope the
/// sheet read: a changed project is refused before anything is made, again when the Analyzing
/// sheet lands, and again after the subjects are read off main. Stop is the Analyzing sheet's
/// own and makes nothing. A Speaker hand-off is not made after its analysis lands: the sheet is
/// presented again from it, so a person confirms each microphone's face before Make (road map
/// creator-jobs VR6b, spec §11 VR-66 (e)). Every refusal beeps and puts its sentence at the inspector's foot
/// (spec §11 CI-10).
extension EditorViewController {

    @objc func showVerticalVersionSheet(_ sender: Any?) {
        guard let document, validateVerticalVersionAction(#selector(showVerticalVersionSheet(_:)))
            == true
        else {
            NSSound.beep()
            return
        }
        presentVerticalSheet(document: document, restoring: nil)
    }

    /// The sheet, fresh or presented again from a Speaker hand-off whose analysis landed.
    private func presentVerticalSheet(document: ProjectDocument, restoring: VerticalHandOff?) {
        presentAsSheet(
            VerticalVersionSheetController(document: document, restoring: restoring) {
                [weak self, weak document] handOff in
                guard let self, let document else { return }
                self.analyzeForVertical(handOff, document: document)
            })
    }

    /// The sheet's hand-off: refused when the project or scope changed since the sheet read it;
    /// else committed at once, or the Analyzing sheet over every missing request, one row each.
    private func analyzeForVertical(_ handOff: VerticalHandOff, document: ProjectDocument) {
        guard document.project === handOff.asked, document.scope == handOff.scope else {
            refuseVertical(
                handOff.requests.isEmpty ? Self.verticalSheetChanged : Self.verticalChanged,
                document: document)
            return
        }
        guard !handOff.requests.isEmpty else {
            commitVertical(handOff, subjects: handOff.subjects, document: document)
            return
        }
        guard view.window?.attachedSheet == nil else {
            NSSound.beep()
            return
        }
        let rows = handOff.requests.map {
            AnalyzingSheetController.Row(name: FollowSubject.rowName($0), request: $0)
        }
        presentAsSheet(
            AnalyzingSheetController(
                document: document, command: VerticalVersion.actionName, rows: rows
            ) { [weak self, weak document] outcome in
                guard let self, let document else { return }
                self.finishVertical(outcome, rows: rows, handOff: handOff, document: document)
            })
    }

    /// The Analyzing sheet's answer: refused when the project or scope changed, a failed
    /// analysis named; else the subjects read off main, checked again, and committed.
    private func finishVertical(
        _ outcome: AnalyzingSheetController.Outcome, rows: [AnalyzingSheetController.Row],
        handOff: VerticalHandOff, document: ProjectDocument
    ) {
        guard document.project === handOff.asked, document.scope == handOff.scope else {
            refuseVertical(Self.verticalChanged, document: document)
            return
        }
        switch outcome {
        case .failed(let name, let why):
            let request = rows.first { $0.name == name }?.request
            let kind = request?.kind.rawValue ?? "framing"
            let file = request?.media.name ?? name
            refuseVertical("The \(kind) analysis of “\(file)” failed: \(why).", document: document)
        case .landed:
            if handOff.settings.follow == .speaker {
                // VR-66 (e): the faces are confirmed on the sheet, never made here.
                guard view.window?.attachedSheet == nil else {
                    NSSound.beep()
                    return
                }
                presentVerticalSheet(document: document, restoring: handOff)
                return
            }
            guard let cacheDir = document.cacheDirectory else {
                refuseVertical(
                    ProjectDocument.AnalysisRequestError.noCache.localizedDescription,
                    document: document)
                return
            }
            let targets = handOff.targets
            let cursor = handOff.cursor
            let asked = handOff.asked
            DispatchQueue.global(qos: .userInitiated).async { [weak self, weak document] in
                var subjects = FollowSubject.subjects(targets, in: asked, cacheDir: cacheDir)
                // A cursor beside the analysis (spec §11 VR-51).
                subjects.merge(FramingCursor.subjects(cursor, in: asked)) { _, new in new }
                DispatchQueue.main.async {
                    guard let self, let document else { return }
                    guard document.project === handOff.asked, document.scope == handOff.scope
                    else {
                        self.refuseVertical(Self.verticalChanged, document: document)
                        return
                    }
                    self.commitVertical(handOff, subjects: subjects, document: document)
                }
            }
        }
    }

    /// VR-39 (g): the plan again on the current handle, then the copy opened in front, or the
    /// step applied in place as one explicit undo group.
    private func commitVertical(
        _ handOff: VerticalHandOff, subjects: [UInt32: [String: Any]], document: ProjectDocument
    ) {
        let answer: VerticalVersion.Answer
        do {
            answer = try VerticalVersion.plan(
                document.project, settings: handOff.settings, subjects: subjects,
                missing: handOff.missing)
        } catch {
            refuseVertical(error.localizedDescription, document: document)
            return
        }
        let plan: VerticalVersion.Plan
        switch answer {
        case .refused(let why):
            refuseVertical(why, document: document)
            return
        case .plan(let made):
            plan = made
        }
        guard handOff.copy else {
            document.performGroupedEdit(VerticalVersion.actionName, plan.ops)
            return
        }
        do {
            _ = try ProjectDocument.verticalCopy(
                from: document, plan: plan, shape: handOff.settings.shape, path: nil,
                display: true)
        } catch {
            refuseVertical(error.localizedDescription, document: document)
        }
    }

    private static let verticalSheetChanged =
        "the project changed while the Make Vertical Version sheet was open, so nothing was "
        + "made. Choose Make Vertical Version again."

    private static let verticalChanged =
        "the project changed while \(VerticalVersion.actionName) was analyzing, so nothing was "
        + "made. Choose Make Vertical Version again."

    /// A beep and the sentence at the inspector's foot.
    private func refuseVertical(_ reason: String, document: ProjectDocument) {
        NSSound.beep()
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: ["refusal": ReelRefusal(op: "set_canvas", reason: reason)])
    }

    /// The menu arm, answered from `validateUserInterfaceItem`'s default case; nil for any other
    /// action. On with a document, no nest open, no sheet on the window, no recording running
    /// and at least one clip in the project (VR-39 (a)).
    func validateVerticalVersionAction(_ action: Selector) -> Bool? {
        guard action == #selector(showVerticalVersionSheet(_:)) else { return nil }
        guard let document else { return false }
        return document.scope == nil && view.window?.attachedSheet == nil
            && !ScreenRecorder.shared.isRecording && !document.project.snapshot.clips.isEmpty
    }
}
import AppKit

/// Make Vertical's copy (spec §11 VR-30, VR-31; road map "creator-jobs" VR3a): CJ5b's derived
/// document handed the source's handle unchanged (`range: nil`, so every media stays and
/// every cache and analysis is carried), named "<source> (<shape>)", with the step applied
/// there as its one undo step, "Make Vertical". The source is never edited and gains no undo
/// step. Its doors are `make_vertical_version` (`AgentServer+VerticalVersion.swift`) and File ▸
/// Make Vertical Version… (`EditorViewController+VerticalVersion.swift`, VR3b). In the copy,
/// and only there, the project's own older copies of the bundled templates are rewritten with
/// the current text (VR-44 (c), `VerticalVersion+Layers.swift`).
extension ProjectDocument {

    /// The copy, what was carried and the template report. Main only. A copy the step did not
    /// change is closed, its package at `path` removed, and the call refused.
    static func verticalCopy(
        from source: ProjectDocument, plan: VerticalVersion.Plan, shape: VerticalShape,
        path: URL?, display: Bool
    ) throws -> (
        document: ProjectDocument, carried: DerivedCarry.Report,
        templates: VerticalVersion.TemplateReport
    ) {
        assert(Thread.isMainThread)
        let made = try derived(
            from: source, handle: source.project, range: nil, path: path, display: display,
            name: "\(source.displayStem) (\(shape.rawValue))")
        let opened = made.document.project
        made.document.performGroupedEdit(VerticalVersion.actionName, plan.ops)
        guard made.document.project !== opened else {
            made.document.close()
            if let path { try? FileManager.default.removeItem(at: path) }
            throw ReelCoreError(
                message: "Make Vertical did not apply to the copy, so nothing was made.")
        }
        var templates = VerticalVersion.TemplateReport()
        if let store = made.document.graphicStore {
            let survey = VerticalVersion.templateSurvey(made.document.project, store: store)
            templates = VerticalVersion.updateTemplates(
                survey, in: store, from: GraphicTemplates.bundledDirectory)
        }
        return (made.document, made.carried, templates)
    }
}

