3	/// Make Vertical's camera layouts (spec §11 VR-53, VR-54; road map "creator-jobs" VR5b): class
4	/// 2b — a clip laid out by Clip ▸ Camera Layout ▸, as a camera, a screen, or a cut piece of one
5	/// — and step 3b, one `reframe_clip {follow: "layout"}` per camera, whose replay is the core's
6	/// (`core/src/reframe_layout.rs`). Swift restates none of the geometry: `isLayoutAction` and
7	/// `sameSource` twin `action_class.rs`'s `is_layout` and `layout_recognise.rs`'s `same_source`
8	/// for the classes, and `layoutName` names, for the summary only, an end the core has already
9	/// recognised. Names no `rc_*`.
10	extension VerticalVersion {
11	
12	    /// One re-laid switch: the camera clip, its absolute start, the layout it was on the old
13	    /// canvas and the one it is now.
14	    struct Relaid: Equatable {
15	        let camera: UInt32
16	        let at: Ticks
17	        let from: CameraLayoutChoice
18	        let to: CameraLayoutKind
19	    }
20	
21	    /// Step 3b's answer: the clips it changed, their entries and the switches, or the refusal
22	    /// that stops the step (a refused `keep`, VR-34).
23	    enum Relayed {
24	        case done(done: Set<UInt32>, entries: [UInt32: Entry], relaid: [Relaid])
25	        case refused(String)
26	    }
27	
28	    /// The reason a layout role or piece no op re-laid is kept with.
29	    static let handEditedReason = "its camera layout was edited by hand, so it is kept as placed"
30	
31	    /// The three roles class 2b gives.
32	    static func isLayoutRole(_ role: Role) -> Bool {
33	        role == .layoutCamera || role == .layoutScreen || role == .layoutPiece
34	    }
35	
36	    /// A layout action: its end's `video` names all six placement keys (`action_class.rs`'s
37	    /// `is_layout`, CO-63).
38	    static func isLayoutAction(_ action: ActionSnapshot) -> Bool {
39	        guard let video = action.end.video else { return false }
40	        return video.x != nil && video.y != nil && video.scale != nil && video.crop != nil
41	            && video.cornerRadius != nil && video.opacity != nil
42	    }
43	
44	    /// The same kind and the same media (a media, still or image source) or nest; `in`, `at`
45	    /// and `reversed` ignored (`same_source`'s twin), so a split half is the same source.
46	    static func sameSource(_ a: ClipSource, _ b: ClipSource) -> Bool {
47	        switch (a, b) {
48	        case (.media(let x, _, _), .media(let y, _, _)): return x == y
49	        case (.still(let x, _), .still(let y, _)): return x == y
50	        case (.image(let x), .image(let y)): return x == y
51	        case (.nest(let x), .nest(let y)): return x == y
52	        default: return false
53	        }
54	    }
55	
56	    /// The absolute starts of `clip`'s layout actions.
57	    private static func layoutStarts(_ clip: ClipSnapshot) -> [Ticks] {
58	        clip.actions.filter(isLayoutAction).map { clip.start + $0.start }
59	    }
60	
61	    /// Whether a base is a layout end within the core's recognition tolerances (1 px, 0.001).
62	    private static func alike(_ video: VideoProps, _ end: VideoPatch) -> Bool {
63	        guard let x = end.x, let y = end.y, let scale = end.scale, let crop = end.crop,
64	            let radius = end.cornerRadius, let opacity = end.opacity
65	        else { return false }
66	        let px = { (a: Double, b: Double) in abs(a - b) <= 1 }
67	        return px(video.x, x) && px(video.y, y) && px(video.crop.l, crop.l)
68	            && px(video.crop.t, crop.t) && px(video.crop.r, crop.r) && px(video.crop.b, crop.b)
69	            && px(video.cornerRadius, radius) && abs(video.scale - scale) <= 0.001
70	            && abs(video.opacity - opacity) <= 0.001
71	    }
72	
73	    /// Class 2b (VR-53 (a)): a clip holding a layout action is a screen when a clip on a track
74	    /// in front holds one starting when one of its own does, else a camera; a clip of the same
75	    /// source as a laid-out clip R on R's track, starting after R's layout action and before
76	    /// the track's next one, whose base is that action's end, is a piece. nil otherwise.
77	    static func layoutRole(
78	        of clip: ClipSnapshot, in snapshot: ProjectSnapshot, order: [UInt32: Int]
79	    ) -> Role? {
80	        let own = order[clip.track] ?? -1
81	        let starts = layoutStarts(clip)
82	        if !starts.isEmpty {
83	            let screen = snapshot.clips.contains { other in
84	                other.id != clip.id && (order[other.track] ?? -1) > own
85	                    && layoutStarts(other).contains(where: starts.contains)
86	            }
87	            return screen ? .layoutScreen : .layoutCamera
88	        }
89	        guard snapshot.sourceSize(of: clip) != nil else { return nil }
90	        let track = snapshot.clips.filter { $0.track == clip.track }
91	        for laid in track where laid.id != clip.id && sameSource(laid.source, clip.source) {
92	            for action in laid.actions where isLayoutAction(action) {
93	                let at = laid.start + action.start
94	                let next = track.flatMap(layoutStarts).filter { $0 > at }.min() ?? .max
95	                if clip.start > at, clip.start < next, let end = action.end.video,
96	                    alike(clip.videoProps, end)
97	                {
98	                    return .layoutPiece
99	                }
100	            }
101	        }
102	        return nil
103	    }
104	
105	    /// Step 3b (VR-53 (d)): one `reframe_clip {follow: "layout"}` from the old canvas per
106	    /// camera in id order, skipped when an earlier one changed it; every clip one changed is
107	    /// done (`relaid`). A refused op is not a stop: each layout role and piece left is kept
108	    /// (`keep`, VR-34's fallback) with `handEditedReason`. `width` × `height` is the new size.
109	    static func relay(
110	        _ roles: [(clip: UInt32, role: Role)], old: ProjectSnapshot, width: Int, height: Int,
111	        trial: inout SwitchAngle.Trial
112	    ) throws -> Relayed {
113	        let from = (UInt32(old.canvas.width), UInt32(old.canvas.height))
114	        var done: Set<UInt32> = []
115	        for (id, role) in roles where role == .layoutCamera && !done.contains(id) {
116	            let op = ReelOp.reframeClip(
117	                clip: id, follow: .layout, fromWidth: from.0, fromHeight: from.1)
118	            let prior = trial.project
119	            guard case .applied(let made) = try prior.applying(op) else { continue }
120	            trial.project = made
121	            trial.ops.append(op)
122	            let after = made.snapshot
123	            for clip in prior.snapshot.clips where after.clip(clip.id) != clip {
124	                done.insert(clip.id)
125	            }
126	        }
127	        var entries: [UInt32: Entry] = [:]
128	        for (id, role) in roles where isLayoutRole(role) || done.contains(id) {
129	            if done.contains(id) {
130	                entries[id] = Entry(clip: id, treatment: .relaid, reason: nil)
131	                continue
132	            }
133	            let keep = ReelOp.reframeClip(
134	                clip: id, follow: .keep, fromWidth: from.0, fromHeight: from.1)
135	            if let why = try trial.require(keep) {
136	                return .refused("Make Vertical was refused at reframe_clip for clip \(id): \(why)")
137	            }
138	            entries[id] = Entry(clip: id, treatment: .notFollowed, reason: handEditedReason)
139	        }
140	        var relaid: [Relaid] = []
141	        let tall = height > width
142	        for (id, role) in roles where role == .layoutCamera && done.contains(id) {
143	            guard let clip = old.clip(id) else { continue }
144	            for action in clip.actions where isLayoutAction(action) {
145	                guard let name = layoutName(action, of: clip, in: old) else { continue }
146	                let to: CameraLayoutKind = tall && name.kind == .sideBySide ? .stacked : name.kind
147	                relaid.append(
148	                    Relaid(camera: id, at: clip.start + action.start, from: name, to: to))
149	            }
150	        }
151	        relaid.sort { ($0.at, $0.camera) < ($1.at, $1.camera) }
152	        return .done(done: done, entries: entries, relaid: relaid)
153	    }
154	
155	    /// The layout a camera's layout end shows on `snapshot`'s canvas (VR-54), for the summary
156	    /// and the answer only: opacity under 0.5 is Screen Only; x, y, every crop edge and the
157	    /// radius under 0.5 Camera Full; a picture within the corner box (0.25 W + 1 × H/3 + 1) a
158	    /// corner — Circle with a crop, Rounded with a radius, else square, the corner by the signs
159	    /// of x and y; else Stacked below the middle, Side by Side otherwise.
160	    static func layoutName(
161	        _ end: ActionSnapshot, of clip: ClipSnapshot, in snapshot: ProjectSnapshot
162	    ) -> CameraLayoutChoice? {
163	        guard let patch = end.end.video, let x = patch.x, let y = patch.y,
164	            let scale = patch.scale, let crop = patch.crop, let radius = patch.cornerRadius,
165	            let opacity = patch.opacity, let size = snapshot.sourceSize(of: clip)
166	        else { return nil }
167	        let kind = { (kind: CameraLayoutKind) in
168	            CameraLayoutChoice(kind: kind, shape: nil, corner: nil)
169	        }
170	        if opacity < 0.5 { return kind(.screenOnly) }
171	        let edges = [crop.l, crop.t, crop.r, crop.b]
172	        if abs(x) < 0.5, abs(y) < 0.5, edges.allSatisfy({ $0 < 0.5 }), radius < 0.5 {
173	            return kind(.cameraFull)
174	        }
175	        var video = clip.videoProps
176	        video.x = x
177	        video.y = y
178	        video.scale = scale
179	        video.crop = crop
180	        let canvas = snapshot.canvas
181	        let (w, h) = (Double(canvas.width), Double(canvas.height))
182	        let rect = canvasRect(of: clip, in: canvas, sourceSize: size, video: video)
183	        if rect.width <= 0.25 * w + 1, rect.height <= h / 3 + 1 {
184	            let shape: CameraLayoutShape =
185	                edges.contains { $0 > 0.5 } ? .circle : radius > 0.5 ? .rounded : .square
186	            let corner: CameraLayoutCorner =
187	                y > 0
188	                ? (x > 0 ? .bottomRight : .bottomLeft) : (x > 0 ? .topRight : .topLeft)
189	            return CameraLayoutChoice(kind: .corner, shape: shape, corner: corner)
190	        }
191	        return kind(rect.midY > h / 2 + 1 ? .stacked : .sideBySide)
192	    }
193	
194	    /// A re-laid switch's summary line (VR-54).
195	    static func relaidLine(_ relaid: Relaid, canvas: CanvasSnapshot) -> String {
196	        let name =
197	            relaid.from.kind == .corner
198	            ? (relaid.from.shape ?? .square).menuTitle : relaid.from.kind.title
199	        let at = ReelTime.format(relaid.at, fps: canvas.fps, frames: canvas.timecodeFrames)
200	        if relaid.to != relaid.from.kind {
201	            return "Re-laid: \(name) → \(relaid.to.title) at \(at)."
202	        }
203	        return "Re-laid: \(name) at \(at)."
204	    }
205	
206	    /// The answer's `relaid` (VR-54): `camera`, `at` in ticks, `from` and `to` in
207	    /// `switch_layout`'s words, and `shape` for a corner.
208	    static func relaidFields(_ relaid: [Relaid]) -> [[String: Any]] {
209	        relaid.map { entry in
210	            var row: [String: Any] = [
211	                "camera": Int(entry.camera), "at": Int(entry.at),
212	                "from": entry.from.kind.rawValue, "to": entry.to.rawValue,
213	            ]
214	            if entry.from.kind == .corner, let shape = entry.from.shape {
215	                row["shape"] = shape.rawValue
216	            }
217	            return row
218	        }
219	    }
220	}
