66	    /// VR-64 (b): the present, cursor-free class-3 media pictures off the microphone tracks whose
67	    /// span overlaps a clip with audio on at least two of them, in id order; [] unless `follow`
68	    /// is `speaker`. Each one's `mics` are, per microphone in order, the media clip with audio on
69	    /// that microphone's track with the greatest overlap (ties: the earlier start, then the lower
70	    /// id); a track with none is left out with its `micFaces` entry. A `micFaces` that is not
71	    /// one per microphone is passed as given, for the core to refuse in its own sentence.
72	    static func speakerClips(
73	        _ project: ReelProject, settings: VerticalSettings, missing: Set<UInt32>
74	    ) -> [SpeakerClip] {
75	        guard settings.follow == .speaker else { return [] }
76	        let snapshot = project.snapshot
77	        let micTracks = settings.mics.map { snapshot.clip($0)?.track }
78	        let onMics = Set(micTracks.compactMap { $0 })
79	        let given = settings.micFaces
80	        let filters = given.map { $0.count == settings.mics.count } ?? false
81	        var out: [SpeakerClip] = []
82	        for id in mediaPictures(classify(project), in: snapshot) where !missing.contains(id) {
83	            guard let clip = snapshot.clip(id), snapshot.media(for: clip)?.cursor == nil,
84	                !onMics.contains(clip.track)
85	            else { continue }
86	            var mics: [UInt32] = []
87	            var faces: [UInt32] = []
88	            for (n, track) in micTracks.enumerated() {
89	                guard let track, let best = loudest(on: track, under: clip, in: snapshot)
90	                else { continue }
91	                mics.append(best)
92	                if filters, let given { faces.append(given[n]) }
93	            }
94	            guard mics.count >= 2 else { continue }
95	            out.append(SpeakerClip(clip: id, mics: mics, micFaces: filters ? faces : given))
96	        }
97	        return out
98	    }
99	
100	    /// The media clip with audio on `track` that overlaps `clip` most (ties: the earlier start,
101	    /// then the lower id); nil when none overlaps it.
102	    private static func loudest(
103	        on track: UInt32, under clip: ClipSnapshot, in snapshot: ProjectSnapshot
104	    ) -> UInt32? {
105	        func overlap(_ other: ClipSnapshot) -> Ticks {
106	            max(0, min(other.end, clip.end) - max(other.start, clip.start))
107	        }
108	        let sounding = snapshot.clips(onTrack: track).filter { other in
109	            guard case .media = other.source, snapshot.media(for: other)?.hasAudio == true
110	            else { return false }
111	            return overlap(other) > 0
112	        }
113	        return sounding.min { a, b in
114	            (-overlap(a), a.start, a.id) < (-overlap(b), b.start, b.id)
115	        }?.id
116	    }
117	
118	    /// VR-64 (d): each speaker clip's subjects with `turns`, read through `FramingSpeaker.turns`
119	    /// over its own microphones; a clip with no subjects is left as it is. Main thread (it reads
120	    /// the document); throws `FramingSpeaker.Refusal`.
121	    static func withTurns(
122	        _ subjects: [UInt32: [String: Any]], speaker: [SpeakerClip], document: ProjectDocument
123	    ) throws -> [UInt32: [String: Any]] {
124	        var out = subjects
125	        let snapshot = document.editedProject.snapshot
126	        for entry in speaker {
127	            guard var own = out[entry.clip], let clip = snapshot.clip(entry.clip) else { continue }
128	            own["turns"] = try FramingSpeaker.turns(
129	                document: document, clip: clip, mics: entry.mics)
130	            out[entry.clip] = own
131	        }
132	        return out
133	    }
134	
135	    /// VR-66 (c): the sheet's reading for Speaker on `project` with the ticked microphones in
136	    /// `settings.mics` — the turns filled, then the core's match on the reference clip (the
137	    /// longest speaker clip, ties to the lower id) with its own microphones. Main thread.
138	    static func speakerReading(
139	        document: ProjectDocument, project: ReelProject, settings: VerticalSettings,
140	        subjects: [UInt32: [String: Any]], missing: Set<UInt32>
141	    ) -> SpeakerReading {
142	        let clips = speakerClips(project, settings: settings, missing: missing)
143	        let snapshot = project.snapshot
144	        let reference = clips.min { a, b in
145	            let (da, db) = (snapshot.clip(a.clip)?.duration ?? 0, snapshot.clip(b.clip)?.duration ?? 0)
146	            return (-da, a.clip) < (-db, b.clip)
147	        }
148	        guard let reference else { return .refused(noSpeakerClipSheet) }
149	        let filled: [UInt32: [String: Any]]
150	        do {
151	            filled = try withTurns(subjects, speaker: clips, document: document)
152	        } catch let refusal as FramingSpeaker.Refusal {
153	            return .refused(refusal.sentence)
154	        } catch {
155	            return .refused(error.localizedDescription)
156	        }
157	        let match = filled[reference.clip].flatMap {
158	            project.speakerMatch(clip: reference.clip, mics: reference.mics, subjects: $0)
159	        }
160	        return .ready(subjects: filled, reference: reference.clip, match: match)
161	    }
162	}
