60	    func makeVerticalVersion(_ a: [String: Any]) throws -> String {
61	        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
62	        guard !Thread.isMainThread else {
63	            throw ToolError(
64	                message: "make_vertical_version must run on the server thread — its name is "
65	                    + "missing from AgentServer.creatorOffMainTools.")
66	        }
67	        let call = try onMain { try self.resolveVertical(a) }
68	        var subjects: [UInt32: [String: Any]] = [:]
69	        if !call.requests.isEmpty {
70	            let clips = call.targets.count
71	            if let analyzing = try waitForAnalysis(
72	                call.requests, document: call.document, stop: stop, unmade: "nothing was made",
73	                note: { percent in
74	                    "Still analyzing the media of \(clips) \(clips == 1 ? "clip" : "clips") "
75	                        + "(\(percent) %); call make_vertical_version again to make the version."
76	                })
77	            {
78	                return analyzing
79	            }
80	        }
81	        if let cacheDir = call.cacheDir, !call.targets.isEmpty {
82	            subjects = FollowSubject.subjects(call.targets, in: call.asked, cacheDir: cacheDir)
83	        }
84	        subjects.merge(FramingCursor.subjects(call.cursor, in: call.asked)) { _, new in new }
85	        var fields: [String: Any] = ["cached": call.requests.isEmpty]
86	        let outcome: VerticalOutcome = try onMain {
87	            let document = call.document
88	            guard document.project === call.asked, document.scope == call.scope else {
89	                throw ToolError(
90	                    message: "the project changed while make_vertical_version read the "
91	                        + "analysis, so nothing was made. Call make_vertical_version again.")
92	            }
93	            // VR-64 (d): who talks when, read on this hop from the microphones' caches.
94	            var filled = subjects
95	            do {
96	                filled = try VerticalVersion.withTurns(
97	                    subjects,
98	                    speaker: VerticalVersion.speakerClips(
99	                        document.project, settings: call.settings, missing: call.missing),
100	                    document: document)
101	            } catch let refusal as FramingSpeaker.Refusal {
102	                throw ToolError(message: "make_vertical_version was refused: " + refusal.sentence)
103	            }
104	            let plan = try self.verticalPlan(
105	                document.project, call.settings, subjects: filled, missing: call.missing)
106	            guard call.copy else {
107	                // In place nothing is written: the old template copies are listed (VR-44 (c)).
108	                let survey = VerticalVersion.templateSurvey(
109	                    document.project, store: document.graphicStore)
110	                fields.merge(
111	                    VerticalVersion.answerFields(
112	                        plan, templates: VerticalVersion.templateReport(survey, copy: false))
113	                ) { _, new in new }
114	                return .applied(
115	                    try self.editResult(document, VerticalVersion.actionName, plan.ops, fields))
116	            }
117	            do {
118	                let made = try ProjectDocument.verticalCopy(
119	                    from: document, plan: plan, shape: call.settings.shape, path: call.url,
120	                    display: Self.derivedDisplay)
121	                // The copy's own report: what it updated and what it listed.
122	                fields.merge(VerticalVersion.answerFields(plan, templates: made.templates)) {
123	                    _, new in new
124	                }
125	                return .copied(made)
126	            } catch {
127	                throw ToolError(message: error.localizedDescription)
128	            }
129	        }
130	        let made: (
131	            document: ProjectDocument, carried: DerivedCarry.Report,
132	            templates: VerticalVersion.TemplateReport
133	        )
134	        switch outcome {
135	        case .applied(let answer): return answer
136	        case .copied(let copy): made = copy
137	        }
138	        if let url = call.url {
139	            try save(made.document, to: url, operation: .saveOperation)
140	            fields["saved"] = url.path
141	        }
142	        return try onMain {
143	            var result: [String: Any] = ["ok": true]
144	            result.merge(fields) { _, new in new }
145	            result["carried"] = [
146	                "files": made.carried.files, "bytes": made.carried.bytes,
147	                "seconds": made.carried.seconds,
148	            ]
149	            result["project"] = self.summary(made.document)
150	            return try self.jsonResult(result)
151	        }
152	    }
