154	    /// The plan on `project`, its refusal thrown in the step's own sentence and the core's
155	    /// invalid input as its message. Main thread.
156	    private func verticalPlan(
157	        _ project: ReelProject, _ settings: VerticalSettings, subjects: [UInt32: [String: Any]],
158	        missing: Set<UInt32>
159	    ) throws -> VerticalVersion.Plan {
160	        let answer: VerticalVersion.Answer
161	        do {
162	            answer = try VerticalVersion.plan(
163	                project, settings: settings, subjects: subjects, missing: missing)
164	        } catch {
165	            throw ToolError(message: error.localizedDescription)
166	        }
167	        switch answer {
168	        case .plan(let plan): return plan
169	        case .refused(let why): throw ToolError(message: why)
170	        }
171	    }
