368	/// Refusal (6): a turned base, an action end turning the clip, or a spin.
369	fn turn_refusal(id: u32, clip: &Clip, video: &VideoProps) -> Option<String> {
370	    let upright = "framing works on an upright picture; only keep reframes it";
371	    if video.rotation != 0.0 {
372	        return Some(format!(
373	            "clip {id} is turned {}°, and {upright}",
374	            video.rotation
375	        ));
376	    }
377	    let turning = |a: &&Action| {
378	        a.end["video"]["rotation"]
379	            .as_f64()
380	            .is_some_and(|r| r != 0.0)
381	    };
382	    if let Some(action) = clip.actions.iter().find(turning) {
383	        return Some(format!(
384	            "clip {id}'s action {} turns it, and {upright}",
385	            action.id
386	        ));
387	    }
388	    let spins = video.motion.as_ref().is_some_and(|m| {
389	        [m.r#in, m.out]
390	            .iter()
391	            .flatten()
392	            .any(|e| e.kind == EdgeMotion::Spin)
393	            || m.during.is_some_and(|d| d.kind == DuringMotion::Spin)
394	    });
395	    spins.then(|| format!("clip {id} spins in its motion, and {upright}"))
396	}
397	//! The framing planner (road map "creator-jobs" VR2a1, spec §11 VR-20,
398	//! VR-22, VR-23): a clip's analysed subjects in, a [`FramingPath`] out — a
399	//! similarity per instant from the canvas the clip was authored for (`Ws ×
400	//! Hs`) to the current one (`W × H`). Pure; nothing here edits.
401	//! `edit_reframe.rs`'s op writes the path as the clip's base and actions
402	//! (`reframe_cover.rs`).
403	//!
404	//! **The frames.** A box is 0…1 of the upright picture from its top-left. Its
405	//! point `(bx, by)` is `u = (bx·mw − mw/2, by·mh − mh/2)` px from the
406	//! UNCROPPED centre (`mw × mh` the media's displayed size), and lands on the
407	//! source canvas at `anchor + s·u` — `edit_zoom.rs`'s (★) at θ = 0, with
408	//! `anchor` and `s` the clip's base `video`. A crop moves only the
409	//! picture's extent, the cropped rect `anchor + s·(c ± (cw/2, ch/2))`, so
410	//! the analysis cache never depends on it.
411	//!
412	//! **The window.** The part of the source canvas the target shows: `W/k ×
413	//! H/k`, where `k·s` is `zoom ×` the fill scale of the cropped picture on
414	//! the target (`Project::fill_scale`), at most `SCALE_MAX`. A key is
415	//! `(k, dx, dy)` with `dx = k·(Ws/2 − wc.x)`, `dy = k·(Hs/2 − wc.y)` for a
416	//! window centred at `wc`; composed into a placement as `scale′ = k·scale,
417	//! x′ = k·x + dx, y′ = k·y + dy` (VR-3, VR-27). Every `wc` is clamped so the
418	//! window lies inside the cropped rect (VR-7's covering key).
419	//!
420	//! **The placement in force** (VR-27 (a)). A clip with actions moves its
421	//! picture under the window: a sample's point is (★) through the clip's
422	//! evaluated placement at its own tick (`Frame.placed`), and the rect the
423	//! window is clamped into is the COMMON one — the cropped rects of the base
424	//! and of the placement at every action's end, intersected — with `k`
425	//! raised until the window fits it, held so `k·s` stays at most `SCALE_MAX`
426	//! at every one of those placements. A clip with no actions is VR2a2's.
427	//!
428	//! **The path.** VR-21 (`reframe_tracks.rs`) chooses a subject per sample;
429	//! VR-22 composes the window on it; `reframe_path.rs` writes the keys —
430	//! VR-23's moves only when the median-filtered subject leaves a dead zone,
431	//! each a hold key and an eased key, and VR-24's hard cuts, loss, return and
432	//! two people — snapped to the canvas's frames. Where there is nothing to
433	//! follow the path holds a `where_empty` state ([`WhereEmpty`]): the window on
434	//! the cropped centre, or the whole cropped picture fitted (`edit_zoom.rs`'s
435	//! solves at θ = 0), which [`fixed_framing`] also answers for `follow`
436	//! `center` and `fit` (VR2a2).
437	
