520	/// The geometry one plan reads: the clip's placement on the source canvas,
521	/// the common cropped rect (VR-27 (a)), and the window.
522	pub(crate) struct Frame {
523	    pub(crate) anchor: Point,
524	    pub(crate) s: f64,
525	    pub(crate) media: Point,
526	    pub(crate) rect: (Point, Point),
527	    /// The placement in force at each in-clip sample tick, `(tick, scale, x,
528	    /// y)`, sorted; empty for a clip with no actions, whose points read the
529	    /// base (VR-27 (a)).
530	    pub(crate) placed: Vec<(Ticks, f64, f64, f64)>,
531	    pub(crate) k: f64,
532	    pub(crate) window: Point,
533	    pub(crate) half_source: Point,
534	    /// The `fit` state as a key of F: `(k, dx, dy)` (VR-24 (h)).
535	    pub(crate) fit: (f64, f64, f64),
536	}
