538	impl Frame {
539	    /// The geometry of `clip`, sized through [`Project::source_size`]; `None`
540	    /// for no size, a base rotation other than 0, a zoom outside 1…4, a zero
541	    /// source canvas, or a crop or scale that leaves no picture.
542	    pub(crate) fn of(project: &Project, clip: &Clip, request: &FramingRequest) -> Option<Frame> {
543	        let video = clip.video.clone().unwrap_or_default();
544	        if video.rotation != 0.0 {
545	            return None;
546	        }
547	        let (mw, mh) = project.source_size(clip)?;
548	        let zoom = request.zoom;
549	        let (ws, hs) = (
550	            f64::from(request.from_width),
551	            f64::from(request.from_height),
552	        );
553	        if mw <= 0.0 || mh <= 0.0 || !(1.0..=4.0).contains(&zoom) || ws <= 0.0 || hs <= 0.0 {
554	            return None;
555	        }
556	        let crop = video.crop;
557	        let (cw, ch) = (mw - crop.l - crop.r, mh - crop.t - crop.b);
558	        let s = video.scale;
559	        if !(cw > 0.0 && ch > 0.0 && s.is_finite() && s > 0.0) {
560	            return None;
561	        }
562	        let anchor = (ws / 2.0 + video.x, hs / 2.0 + video.y);
563	        let c = ((crop.l - crop.r) / 2.0, (crop.t - crop.b) / 2.0);
564	        let rect_of = |s: f64, anchor: Point| {
565	            (
566	                (
567	                    anchor.0 + s * (c.0 - cw / 2.0),
568	                    anchor.1 + s * (c.1 - ch / 2.0),
569	                ),
570	                (
571	                    anchor.0 + s * (c.0 + cw / 2.0),
572	                    anchor.1 + s * (c.1 + ch / 2.0),
573	                ),
574	            )
575	        };
576	        let base_rect = rect_of(s, anchor);
577	        let (w, h) = (
578	            f64::from(project.canvas.width),
579	            f64::from(project.canvas.height),
580	        );
581	        // VR-27 (a): the common rect over the base and every action's end,
582	        // and the largest scale among them.
583	        let (mut rect, mut s_max) = (base_rect, s);
584	        for a in &clip.actions {
585	            let p = project
586	                .evaluate_clip(clip, a.start.saturating_add(a.duration))
587	                .video;
588	            if !(p.scale.is_finite() && p.scale > 0.0 && p.x.is_finite() && p.y.is_finite()) {
589	                continue;
590	            }
591	            let ((x0, y0), (x1, y1)) = rect_of(p.scale, (ws / 2.0 + p.x, hs / 2.0 + p.y));
592	            rect = (
593	                (rect.0 .0.max(x0), rect.0 .1.max(y0)),
594	                (rect.1 .0.min(x1), rect.1 .1.min(y1)),
595	            );
596	            s_max = s_max.max(p.scale);
597	        }
598	        let ((x0, y0), (x1, y1)) = rect;
599	        if !(x0 < x1 && y0 < y1) {
600	            rect = base_rect;
601	        }
602	        let mut k = (zoom * project.fill_scale(cw, ch)).min(SCALE_MAX) / s;
603	        // Only a smaller rect raises `k`, so an action-free clip's `k` is
604	        // VR2a2's to the bit.
605	        let raised = rect != base_rect;
606	        if raised {
607	            let ((x0, y0), (x1, y1)) = rect;
608	            k = k.max(w / (x1 - x0)).max(h / (y1 - y0));
609	        }
610	        if raised || s_max > s {
611	            k = k.min(SCALE_MAX / s_max);
612	        }
613	        // Fit: the cropped picture fitted at θ = 0 by `edit_zoom.rs`'s two
614	        // solves, written as F so it composes like any key.
615	        let whole = ZoomRegion {
616	            x: 0.0,
617	            y: 0.0,
618	            width: cw,
619	            height: ch,
620	        };

620	        };
621	        let fit_scale = zoom_scale((w, h), &whole, ZoomFit::Fit, 0.0);
622	        let (fx, fy) = zoom_offset(&video, &whole, fit_scale);
623	        let kf = fit_scale / s;
624	        Some(Frame {
625	            anchor,
626	            s,
627	            media: (mw, mh),
628	            rect,
629	            k,
630	            window: (w / k, h / k),
631	            half_source: (ws / 2.0, hs / 2.0),
632	            fit: (kf, fx - kf * video.x, fy - kf * video.y),
633	            placed: Vec::new(),
634	        })
635	    }
636	
637	    /// A box point (0…1 of the picture) on the source canvas, through the
638	    /// placement in force at clip tick `t` (VR-27 (a)); the base's when
639	    /// none was read there.
640	    pub(crate) fn point(&self, t: Ticks, bx: f64, by: f64) -> Point {
641	        let (mw, mh) = self.media;
642	        let (s, anchor) = match self.placed.binary_search_by_key(&t, |p| p.0) {
643	            Ok(i) => {
644	                let (_, s, x, y) = self.placed[i];
645	                (s, (self.half_source.0 + x, self.half_source.1 + y))
646	            }
647	            Err(_) => (self.s, self.anchor),
648	        };
649	        (
650	            anchor.0 + s * (bx * mw - mw / 2.0),
651	            anchor.1 + s * (by * mh - mh / 2.0),
652	        )
653	    }
654	
655	    /// `wc` moved so the window lies inside the cropped rect (its centre
656	    /// when the window is the larger).
657	    pub(crate) fn clamp(&self, wc: Point) -> Point {
658	        let ((x0, y0), (x1, y1)) = self.rect;
659	        let axis = |v: f64, lo: f64, hi: f64| {
660	            if lo > hi {
661	                (lo + hi) / 2.0
662	            } else {
663	                v.clamp(lo, hi)
664	            }
665	        };
666	        (
667	            axis(wc.0, x0 + self.window.0 / 2.0, x1 - self.window.0 / 2.0),
668	            axis(wc.1, y0 + self.window.1 / 2.0, y1 - self.window.1 / 2.0),
669	        )
670	    }
671	
672	    /// The cropped rect's centre.
673	    pub(crate) fn centre(&self) -> Point {
674	        let ((x0, y0), (x1, y1)) = self.rect;
675	        ((x0 + x1) / 2.0, (y0 + y1) / 2.0)
676	    }
677	
678	    /// The `fit` state's key at `t`.
679	    pub(crate) fn fit_key(&self, t: Ticks, curve: Curve) -> FramingKey {
680	        let (scale, x, y) = self.fit;
681	        FramingKey {
682	            t,
683	            scale,
684	            x,
685	            y,
686	            curve,
687	        }
688	    }
689	
690	    pub(crate) fn key(&self, t: Ticks, wc: Point, curve: Curve) -> FramingKey {
691	        FramingKey {
692	            t,
693	            scale: self.k,
694	            x: self.k * (self.half_source.0 - wc.0),
695	            y: self.k * (self.half_source.1 - wc.1),
696	            curve,
697	        }
698	    }
699	
700	    /// VR-22: the subject point of a kind's box at clip tick `t`, and the
701	    /// window centre's offset from it.
702	    pub(crate) fn subject(
703	        &self,
704	        t: Ticks,
705	        kind: SubjectKind,
706	        b: &SubjectBox,
707	        headroom: f64,
708	    ) -> (Point, Point) {
709	        let (w, h) = self.window;
710	        match kind {
711	            SubjectKind::Face => {
712	                let lift = if h > w { h / 2.0 - headroom * h } else { 0.0 };
713	                (self.point(t, b.x + b.w / 2.0, b.y + b.h / 2.0), (0.0, lift))
714	            }
715	            SubjectKind::Person => (
716	                self.point(t, b.x + b.w / 2.0, b.y),
717	                (0.0, h / 2.0 - PERSON_TOP * h),
718	            ),
719	            SubjectKind::Salient => (self.point(t, b.x + b.w / 2.0, b.y + b.h / 2.0), (0.0, 0.0)),
720	        }
721	    }
722	}
