772	/// The planner (spec §11 VR-20…VR-24). `None` for: no such clip, not a
773	/// media clip of a video media, a base rotation other than 0, a media with
774	/// no size, a crop or scale that leaves no picture, a zoom outside 1…4, or a
775	/// zero `from_width`/`from_height`. VR2a2 refuses each by name before
776	/// calling.
777	pub fn plan_framing(
778	    project: &Project,
779	    clip: u32,
780	    subjects: &Subjects,
781	    request: &FramingRequest,
782	    tuning: &FramingTuning,
783	) -> Option<FramingPath> {
784	    let clip = project.clip(clip)?;
785	    let Source::Media { media, .. } = clip.source else {
786	        return None;
787	    };
788	    let media = project.media(media)?;
789	    if media.kind != MediaKind::Video || !media.has_video {
790	        return None;
791	    }
792	    let mut frame = Frame::of(project, clip, request)?;
793	    let (samples, shots) = in_clip_time(clip, project, subjects);
794	    if !clip.actions.is_empty() {
795	        frame.placed = samples
796	            .iter()
797	            .map(|s| {
798	                let p = project.evaluate_clip(clip, s.t).video;
799	                (s.t, p.scale, p.x, p.y)
800	            })
801	            .collect();
802	    }
803	    let chosen = choose_subject(&samples, &shots, request.follow);
804	    Some(write_keys(
805	        &frame,
806	        &chosen,
807	        &shots,
808	        clip.duration,
809	        project.canvas.fps,
810	        request,
811	        tuning,
812	    ))
813	}
