224	/// The framing (spec §11 VR-60, VR-61): `mics` checked by the op before;
225	/// `Err` is the refusal's sentence, in VR-60 (d)'s order.
226	pub fn plan_speaker_framing(
227	    project: &Project,
228	    clip: u32,
229	    subjects: &Subjects,
230	    mics: &[u32],
231	    mic_faces: Option<&[u32]>,
232	    zoom: f64,
233	    where_empty: WhereEmpty,
234	) -> Result<FramingPath, String> {
235	    let picture = || format!("clip {clip}'s crop or scale leaves no picture to frame");
236	    let c = project.clip(clip).ok_or_else(picture)?;
237	    let Source::Media { media, .. } = c.source else {
238	        return Err(picture());
239	    };
240	    if !project
241	        .media(media)
242	        .is_some_and(|m| m.kind == MediaKind::Video && m.has_video)
243	    {
244	        return Err(picture());
245	    }
246	    if let Some((i, turn)) = subjects
247	        .turns
248	        .iter()
249	        .enumerate()
250	        .find(|(_, u)| !mics.contains(&u.mic))
251	    {
252	        return Err(format!(
253	            "subjects turns[{i}] names clip {}, which is not one of mics",
254	            turn.mic
255	        ));
256	    }
257	    let request = FramingRequest {
258	        follow: Follow::Face,
259	        zoom,
260	        from_width: project.canvas.width,
261	        from_height: project.canvas.height,
262	        where_empty,
263	    };
264	    let mut frame = Frame::of(project, c, &request).ok_or_else(picture)?;
265	    let (samples, shots) = in_clip_time(c, project, subjects);
266	    if let Some(&shot) = shots.first() {
267	        return Err(format!(
268	            "clip {clip} changes shot at {}; follow speaker frames one wide shot — split the \
269	             clip at its shot changes first",
270	            project.layout_timecode(c.start + shot)
271	        ));
272	    }
273	    if !c.actions.is_empty() {
274	        frame.placed = samples
275	            .iter()
276	            .map(|s| {
277	                let p = project.evaluate_clip(c, s.t).video;
278	                (s.t, p.scale, p.x, p.y)
279	            })
280	            .collect();
281	    }
282	    let turns = clip_turns(c, &subjects.turns);
283	    let faces = faces_of(&samples);
284	    let plural = |n: usize| if n == 1 { "face" } else { "faces" };
285	    let Some(found) = matched(&samples, &faces, &turns, mics) else {
286	        return Err(format!(
287	            "clip {clip} shows {} {} for {} microphones; follow speaker needs a face for each \
288	             microphone",
289	            faces.len(),
290	            plural(faces.len()),
291	            mics.len()
292	        ));
293	    };
294	    if let Some(&f) = mic_faces
295	        .into_iter()
296	        .flatten()
297	        .find(|&&f| f as usize > faces.len())
298	    {
299	        return Err(format!(
300	            "mic_faces names face {f}, but clip {clip} shows only {} {}",
301	            faces.len(),
302	            plural(faces.len())
303	        ));
304	    }
305	    let no_turn = || {
306	        format!(
307	            "clip {clip} has no turn of its microphones inside it, so there is no speaker to \
308	             follow"
309	        )
310	    };
311	    if turns.is_empty() {
312	        return Err(no_turn());
313	    }
314	    let assignment: Vec<u32> = match mic_faces {
315	        Some(given) => given.to_vec(),
316	        None if found.sure => found.assignment.clone(),
317	        None => {
318	            let least = (0..mics.len())
319	                .map(|m| found.agreement[m][found.assignment[m] as usize - 1])
320	                .fold(f64::INFINITY, f64::min);
321	            let places: Vec<String> = found
322	                .faces
323	                .iter()
324	                .enumerate()
325	                .map(|(n, f)| {
326	                    let at = format!("face {} at {} %", f.face, (f.x * 100.0).round());
327	                    if n == 0 {
328	                        format!("{at} across the picture")
329	                    } else {
330	                        at
331	                    }
332	                })
333	                .collect();
334	            return Err(format!(
335	                "clip {clip}'s faces do not show which microphone is whose: the best match \
336	                 agrees only {least:.2} (under {SPEAKER_AGREEMENT}); name each microphone's face \
337	                 with mic_faces, in mics' order — {}",
338	                places.join(", ")
339	            ));
340	        }
341	    };
342	    let index: Vec<usize> = assignment.iter().map(|&f| f as usize - 1).collect();
343	    let fits = |a: usize, b: usize, from: Ticks, to: Ticks| {
344	        let widened = |f: usize| {
345	            let m = median_box(&faces[f], &samples, from, to);
346	            let (cx, cy) = centre(&m);
347	            let (w, h) = (m.w * PAIR_WIDEN, m.h * PAIR_WIDEN);
348	            (cx - w / 2.0, cy - h / 2.0, cx + w / 2.0, cy + h / 2.0)
349	        };
350	        let (p, q) = (widened(a), widened(b));
351	        let p0 = frame.point(from, p.0.min(q.0), p.1.min(q.1));
352	        let p1 = frame.point(from, p.2.max(q.2), p.3.max(q.3));
353	        p1.0 - p0.0 <= frame.window.0 && p1.1 - p0.1 <= frame.window.1
354	    };
355	    let segments = segments(c.duration, &turns, mics, &index, fits).ok_or_else(no_turn)?;
356	    let cuts: Vec<Ticks> = segments.iter().map(|s| s.from).filter(|&t| t > 0).collect();
357	    let chosen: Vec<Chosen> = samples
358	        .iter()
359	        .enumerate()
360	        .map(|(i, s)| {
361	            let n = segments
362	                .partition_point(|g| g.to <= s.t)
363	                .min(segments.len() - 1);
364	            let (face, other) = match segments[n].label {
365	                Label::Face(f) => (f, None),
366	                Label::Both(f, o) => (f, Some(o)),
367	            };
368	            Chosen {
369	                t: s.t,
370	                kind: Some(SubjectKind::Face),
371	                track: Some(face as u32 + 1),
372	                subject: faces[face].at(i),
373	                identity: Some(face as u32 + 1),
374	                lost: false,
375	                second: other.and_then(|o| faces[o].at(i)),
376	            }
377	        })
378	        .collect();
379	    Ok(write_keys(
380	        &frame,
381	        &chosen,
382	        &cuts,
383	        c.duration,
384	        project.canvas.fps,
385	        &request,
386	        &FRAMING_TUNING,
387	    ))
388	}
389	//! `reframe_clip {follow: "layout"}` — a camera and the screen behind it
390	//! re-laid on the current canvas (road map "creator-jobs" VR5b, spec §11
391	//! VR-53). Each switch Clip ▸ Camera Layout ▸ made is recognised on the
392	//! AUTHORED canvas (`from`, `layout_recognise.rs`) and solved again here by
393	//! `switch_layout`'s own composition (`compose_switch`), so a re-laid switch
394	//! is exactly the one a person would make on this canvas.
395	//!
396	//! - **The group.** Every top-level clip holding a layout action
397	//!   (`is_layout`) is laid out. A camera action at absolute T pairs with the
398	//!   layout action starting at T on the front-most track behind the
399	//!   camera's that holds one (CO-64's front and behind); a laid-out clip is
400	//!   a SCREEN when one on a track in front holds a layout action starting
401	//!   when one of its own does, else a CAMERA. The group is the closure over
402	//!   pairing from the given clip, plus each switch's PIECES: the clips of the
403	//!   same source (`same_source`, which ignores `in`) on a role's track
404	//!   starting after its action and before the track's next layout action,
405	//!   whose base is `alike` that action's end — the cut pieces of a laid-out
406	//!   recording, which CO-61's reach gave the layout as their base.
407	//! - **The replay.** Every group clip and piece takes `keep`'s per-axis
408	//!   rescale of its BASE (`rescale_video`); the group's layout actions are
409	//!   removed; the switches are composed again in time order at the camera
410	//!   action's absolute start, with [`switch_timing`]'s duration and curve,
411	//!   the recognised layout (Side by Side as Stacked on a canvas taller than
412	//!   wide) and its pieces as each role's later clips, nothing ending a
413	//!   reach. The focus is the old crop's centre (`focus_of`).
414	//! - **The other moves.** Each other moving end of a group clip or piece (a
415	//!   zoom) is re-based by [`conjugate`] from the placement in effect at its
416	//!   start on the old project to the one on the new, so what it zooms on
417	//!   keeps its place in the picture.
418	//!
419	//! Refused in VR-53 (c)'s order (`edit.rs`'s row); CO-62's refusals are not
420	//! asked again: each switch passed them when it was made.
421	
422	use std::collections::{BTreeSet, HashMap};
423	
424	use serde_json::{Map, Value};
425	
426	use crate::action_class::{is_layout, moves};
427	use crate::edit_canvas::rescale_video;
428	use crate::edit_layout_reach::{Role, RoleKind};
429	use crate::layout::{CameraLayout, LayoutChoice, Placement, DEFAULT_SWITCH};
430	use crate::layout_recognise::{alike, recognise, same_source};
431	use crate::model::{Action, Clip, Curve, Project};
432	use crate::outcome::Outcome;
433	use crate::props_check::{SCALE_MAX, SCALE_MIN};
434	use crate::time::Ticks;
435	
436	/// One layout action: its clip, its id and its absolute start.
437	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
438	struct Act {
439	    clip: u32,
440	    action: u32,
441	    at: Ticks,
442	}
443	
444	/// A recognised switch: the camera's action, the screen's paired one, the
445	/// layout, and each role's pieces.
446	struct Switch {
447	    camera: Act,
448	    screen: Option<Act>,
449	    choice: LayoutChoice,
450	    camera_pieces: Vec<u32>,
451	    screen_pieces: Vec<u32>,
452	}
453	
454	/// The duration and curve a switch is replayed with: those of its longest
455	/// role action that does not start at its clip's first frame (a cut there
456	/// is one frame long whatever the switch's length), else the camera
457	/// action's — `actions` holds the camera's first.
458	pub(crate) fn switch_timing(actions: &[(&Clip, &Action)]) -> (Ticks, Curve) {
459	    let mut chosen: Option<&Action> = None;
460	    for (_, action) in actions {
461	        if action.start != 0 && chosen.is_none_or(|c| action.duration > c.duration) {
462	            chosen = Some(action);
463	        }
464	    }
465	    match chosen.or(actions.first().map(|(_, a)| *a)) {
466	        Some(action) => (action.duration, action.curve),
467	        None => (DEFAULT_SWITCH, Curve::EaseInOut),
468	    }
469	}
470	
471	/// A moving end re-based from the placement `old` it was made over to
472	/// `new`: with `r = new.scale / old.scale`, each of `x`, `y` and `scale`
473	/// the end names is written `new.x + r·(x − old.x)`, `new.y + r·(y − old.y)`
474	/// and `scale·r` (clamped), so the picture point it shows at a canvas point
475	/// keeps its place relative to the layout's picture.
476	pub(crate) fn conjugate(end: &mut Map<String, Value>, old: &Placement, new: &Placement) {
477	    let r = new.scale / old.scale;
478	    if !(r.is_finite() && r > 0.0) {
479	        return;
480	    }
481	    let read = |end: &Map<String, Value>, key: &str| end.get(key).and_then(Value::as_f64);
482	    if let Some(x) = read(end, "x") {
483	        end.insert("x".into(), Value::from(new.x + r * (x - old.x)));
484	    }
485	    if let Some(y) = read(end, "y") {
486	        end.insert("y".into(), Value::from(new.y + r * (y - old.y)));
487	    }
488	    if let Some(scale) = read(end, "scale") {
489	        end.insert(
490	            "scale".into(),
491	            Value::from((scale * r).clamp(SCALE_MIN, SCALE_MAX)),
492	        );
493	    }
494	}
495	
496	/// The layout actions of `clip`, in its action order.
497	fn layout_acts(clip: &Clip) -> Vec<Act> {
498	    clip.actions
499	        .iter()
500	        .filter(|a| is_layout(a))
501	        .map(|a| Act {
502	            clip: clip.id,
503	            action: a.id,
504	            at: clip.start.saturating_add(a.start),
505	        })
506	        .collect()
507	}
508	
509	/// The placement in effect at clip time `t`: the latest layout end starting
510	/// at or before it, else the base.
511	fn in_effect(clip: &Clip, t: Ticks) -> Placement {
512	    clip.actions
513	        .iter()
514	        .filter(|a| is_layout(a) && a.start <= t)
515	        .max_by_key(|a| (a.start, a.id))
516	        .and_then(|a| Placement::from_end(&a.end))
517	        .unwrap_or_else(|| Placement::of(&clip.video.clone().unwrap_or_default()))
518	}
519	
520	impl Project {
521	    /// The layout action starting at absolute `at` on the front-most track
522	    /// behind `camera`'s that holds one.
523	    fn paired(&self, camera: &Clip, at: Ticks) -> Option<Act> {
524	        let front = self.track_index(camera.track)?;
525	        self.tracks.get(..front)?.iter().rev().find_map(|track| {
526	            self.clips
527	                .iter()
528	                .filter(|c| c.track == track.id && c.id != camera.id)
529	                .flat_map(layout_acts)
530	                .filter(|act| act.at == at)
531	                .min_by_key(|act| (act.clip, act.action))
532	        })
533	    }
534	
535	    /// Whether a laid-out clip on a track in front of `clip`'s holds a
536	    /// layout action starting when one of `clip`'s does.
537	    fn is_screen(&self, clip: &Clip) -> bool {
538	        let Some(own) = self.track_index(clip.track) else {
539	            return false;
540	        };
541	        let starts: Vec<Ticks> = layout_acts(clip).iter().map(|a| a.at).collect();
542	        self.clips.iter().any(|c| {
543	            c.id != clip.id
544	                && self.track_index(c.track).is_some_and(|i| i > own)
545	                && layout_acts(c).iter().any(|a| starts.contains(&a.at))
546	        })
547	    }
548	
549	    /// `act`'s clip and action.
550	    fn action_of(&self, act: &Act) -> Option<(&Clip, &Action)> {
551	        let owner = self.clip(act.clip)?;
552	        Some((owner, owner.actions.iter().find(|a| a.id == act.action)?))
553	    }
554	
555	    /// `act`'s end, and its clip's source size.
556	    fn end_of(&self, act: &Act) -> Option<(Placement, (f64, f64))> {
557	        let (owner, action) = self.action_of(act)?;
558	        Some((Placement::from_end(&action.end)?, self.source_size(owner)?))
559	    }
560	
561	    /// The pieces of `act`'s role (the module doc).
562	    fn pieces(&self, act: &Act) -> Vec<u32> {
563	        let Some((role, action)) = self.action_of(act) else {
564	            return Vec::new();
565	        };
566	        let Some(end) = Placement::from_end(&action.end) else {
567	            return Vec::new();
568	        };
569	        let next = self
570	            .clips
571	            .iter()
572	            .filter(|c| c.track == role.track)
573	            .flat_map(layout_acts)
574	            .map(|a| a.at)
575	            .filter(|&t| t > act.at)
576	            .min()
577	            .unwrap_or(Ticks::MAX);
578	        let mut found: Vec<&Clip> = self
579	            .clips
580	            .iter()
581	            .filter(|c| {
582	                c.id != role.id
583	                    && c.track == role.track
584	                    && same_source(&c.source, &role.source)
585	                    && c.start > act.at
586	                    && c.start < next
587	                    && self.has_layout_picture(c)
588	                    && c.video
589	                        .as_ref()
590	                        .is_some_and(|v| alike(&Placement::of(v), &end))
591	            })
592	            .collect();
593	        found.sort_by_key(|c| (c.start, c.id));
594	        found.iter().map(|c| c.id).collect()
595	    }
596	
597	    /// The first unrecognised switch's refusal, by its role's action.
598	    fn unrecognised(&self, act: &Act, from: (u32, u32)) -> Outcome {
599	        Outcome::Refused(format!(
600	            "clip {}'s layout action {} at {} is not a camera layout Frame Job made on the {} × {} \
601	             canvas, so it cannot be re-laid; keep its clips as placed",
602	            act.clip,
603	            act.action,
604	            self.layout_timecode(act.at),
605	            from.0,
606	            from.1
607	        ))
608	    }
609	
610	    /// `follow: layout` on `clip`, authored on a `from` canvas (the module
611	    /// doc).
612	    pub(crate) fn relaid(&self, clip: u32, from: (u32, u32)) -> Result<Outcome, String> {
613	        let given = self.require_clip(clip)?;
614	        if !given.actions.iter().any(is_layout) {
615	            return Ok(Outcome::Refused(format!(
616	                "clip {clip} holds no camera layout to re-lay; frame it with subject, center, fit \
617	                 or keep"
618	            )));
619	        }
620	        // Pairing over every laid-out clip, then the closure from `clip`.
621	        let edges: Vec<(Act, Act)> = self
622	            .clips
623	            .iter()
624	            .flat_map(|c| layout_acts(c).into_iter().map(move |act| (c, act)))
625	            .filter_map(|(c, act)| Some((act, self.paired(c, act.at)?)))
626	            .collect();
627	        let mut group: BTreeSet<u32> = BTreeSet::from([clip]);
628	        loop {
629	            let before = group.len();
630	            for (a, b) in &edges {
631	                if group.contains(&a.clip) || group.contains(&b.clip) {
632	                    group.insert(a.clip);
633	                    group.insert(b.clip);
634	                }
635	            }
636	            if group.len() == before {
637	                break;
638	            }
639	        }
640	        let clips: Vec<&Clip> = group.iter().filter_map(|id| self.clip(*id)).collect();
641	        let screens: HashMap<u32, bool> = clips.iter().map(|c| (c.id, self.is_screen(c))).collect();
642	
643	        // A clip both a camera and a screen.
644	        if let Some(both) = clips
645	            .iter()
646	            .find(|c| screens[&c.id] && edges.iter().any(|(a, _)| a.clip == c.id))
647	        {
648	            return Ok(Outcome::Refused(format!(
649	                "clip {} is laid out both as a camera and as a screen, so its layouts cannot be \
650	                 re-laid; keep its clips as placed",
651	                both.id
652	            )));
653	        }
654	        // A screen action with no camera switch in front of it.
655	        let unpaired = clips
656	            .iter()
657	            .filter(|c| screens[&c.id])
658	            .flat_map(|c| layout_acts(c))
659	            .filter(|act| !edges.iter().any(|(_, s)| s == act))
660	            .min_by_key(|act| (act.at, act.clip, act.action));
661	        if let Some(act) = unpaired {
662	            return Ok(Outcome::Refused(format!(
663	                "clip {}'s layout action {} at {} has no camera switch in front of it, so it \
664	                 cannot be re-laid; keep its clips as placed",
665	                act.clip,
666	                act.action,
667	                self.layout_timecode(act.at)
668	            )));
669	        }
670	
671	        // Each switch recognised on the authored canvas, in time order.
672	        let mut authored = self.clone();
673	        authored.canvas.width = from.0;
674	        authored.canvas.height = from.1;
675	        let mut acts: Vec<Act> = clips
676	            .iter()
677	            .filter(|c| !screens[&c.id])
678	            .flat_map(|c| layout_acts(c))
679	            .collect();
680	        acts.sort_by_key(|act| (act.at, act.clip, act.action));
681	        let mut switches: Vec<Switch> = Vec::new();
682	        for camera in acts {
683	            let screen = edges.iter().find(|(a, _)| *a == camera).map(|(_, s)| *s);
684	            let found = match (self.end_of(&camera), screen.map(|s| self.end_of(&s))) {
685	                (None, _) => Err(RoleKind::Camera),
686	                (Some(_), Some(None)) => Err(RoleKind::Screen),
687	                (Some(cam), shown) => {
688	                    let shown = shown.flatten();
689	                    let shown = shown.as_ref().map(|(end, size)| (end, *size));
690	                    recognise(&authored, &cam.0, cam.1, shown)
691	                }
692	            };
693	            let choice = match found {
694	                Ok(choice) => choice,
695	                Err(kind) => {
696	                    let named = screen.filter(|_| kind == RoleKind::Screen);
697	                    return Ok(self.unrecognised(&named.unwrap_or(camera), from));
698	                }
699	            };
700	            switches.push(Switch {
701	                camera,
702	                screen,
703	                choice,
704	                camera_pieces: self.pieces(&camera),
705	                screen_pieces: screen.map_or_else(Vec::new, |s| self.pieces(&s)),
706	            });
707	        }
708	
709	        // The members: the group's clips and every switch's pieces.
710	        let mut members: BTreeSet<u32> = group.clone();
711	        for s in &switches {
712	            members.extend(s.camera_pieces.iter().chain(&s.screen_pieces));
713	        }
714	        let (w, h) = (
715	            f64::from(self.canvas.width) / f64::from(from.0),
716	            f64::from(self.canvas.height) / f64::from(from.1),
717	        );
718	        let mut next = self.clone();
719	        for c in next.clips.iter_mut().filter(|c| members.contains(&c.id)) {
720	            if let Some(video) = c.video.as_mut() {
721	                rescale_video(video, w, h);
722	            }
723	            if group.contains(&c.id) {
724	                c.actions.retain(|a| !is_layout(a));
725	            }
726	        }
727	
728	        // The replay, in time order.
729	        let tall = self.canvas.height > self.canvas.width;
730	        for s in &switches {
731	            let mut choice = s.choice;
732	            if tall && choice.layout == CameraLayout::SideBySide {
733	                choice.layout = CameraLayout::Stacked;
734	            }
735	            let timed: Vec<(&Clip, &Action)> = std::iter::once(s.camera)
736	                .chain(s.screen)
737	                .filter_map(|act| self.action_of(&act))
738	                .collect();
739	            let (duration, curve) = switch_timing(&timed);
740	            let outcome = {
741	                let role = |kind: RoleKind, act: &Act, pieces: &[u32]| -> Option<Role<'_>> {
742	                    Some(Role {
743	                        kind,
744	                        clip: next.clip(act.clip)?,
745	                        at: act.at,
746	                        later: pieces.iter().filter_map(|id| next.clip(*id)).collect(),
747	                        ender: None,
748	                    })
749	                };
750	                let mut roles = Vec::new();
751	                roles.extend(role(RoleKind::Camera, &s.camera, &s.camera_pieces));
752	                if let Some(screen) = &s.screen {
753	                    roles.extend(role(RoleKind::Screen, screen, &s.screen_pieces));
754	                }
755	                next.compose_switch(&choice, &roles, s.camera.at, duration, curve)
756	            };
757	            match outcome? {
758	                Outcome::Applied(applied) => next = applied,
759	                Outcome::Identity => {}
760	                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
761	            }
762	        }
763	
764	        // The other moving ends, re-based.
765	        for id in &members {
766	            let (Some(old), Some(new)) = (self.clip(*id), next.clip(*id)) else {
767	                continue;
768	            };
769	            let bases: Vec<(usize, Placement, Placement)> = new
770	                .actions
771	                .iter()
772	                .enumerate()
773	                .filter(|(_, a)| moves(a) && !is_layout(a))
774	                .map(|(i, a)| (i, in_effect(old, a.start), in_effect(new, a.start)))
775	                .collect();
776	            let Some(target) = next.clips.iter_mut().find(|c| c.id == *id) else {
777	                continue;
778	            };
779	            for (i, was, now) in bases {
780	                if let Some(Value::Object(end)) = target.actions[i].end.get_mut("video") {
781	                    conjugate(end, &was, &now);
782	                }
783	            }
784	        }
785	        self.finish(next)
786	    }
787	}
788	//! A camera layout recognised from the placements it wrote (road map
789	//! "creator-jobs" VR5b, spec §11 VR-53 (b)): the layout, shape and corner
790	//! whose solve on the AUTHORED canvas gives a switch's camera end and its
791	//! screen end. Pure; beside `layout.rs`, which is at its 400-line cap, and
792	//! read only by `reframe_layout.rs`.
793	//!
794	//! The candidates are tried in a fixed order — `corner` with each shape
795	//! (square, rounded, circle) at each corner (bottom right, bottom left, top
796	//! right, top left), `side_by_side`, `stacked` (both skipped when the switch
797	//! has no screen), `camera_full`, `screen_only` — and the first whose camera
798	//! AND screen placements are [`alike`] the ends wins. A candidate is solved
799	//! with the camera end's own crop centre as its `focus` ([`focus_of`]), so a
800	//! crop centred on a person (CO-70) is recognised whatever the focus was;
801	//! the tolerance is `RECOGNISE_PX` in every pixel-valued key (a switch's
802	//! `x` and `y` are whole pixels, its crop and radius are not) and
803	//! `RECOGNISE_RATIO` in scale and opacity, so an end moved by hand by more
804	//! than a pixel is not a layout Frame Job made.
805	
806	use crate::edit_layout_reach::RoleKind;
807	use crate::layout::{
808	    camera_placement, screen_placement, CameraLayout, LayoutChoice, LayoutCorner, LayoutShape,
809	    Placement,
810	};
811	use crate::model::{Project, Source};
812	
813	/// The tolerance on x, y, the four crop edges and the radius, in pixels.
814	pub(crate) const RECOGNISE_PX: f64 = 1.0;
815	/// The tolerance on scale and opacity.
816	pub(crate) const RECOGNISE_RATIO: f64 = 0.001;
817	
818	/// Whether `got` is `solved` within the recognition tolerances.
819	pub(crate) fn alike(got: &Placement, solved: &Placement) -> bool {
820	    let px = |a: f64, b: f64| (a - b).abs() <= RECOGNISE_PX;
821	    let ratio = |a: f64, b: f64| (a - b).abs() <= RECOGNISE_RATIO;
822	    px(got.x, solved.x)
823	        && px(got.y, solved.y)
824	        && px(got.crop.l, solved.crop.l)
825	        && px(got.crop.t, solved.crop.t)
826	        && px(got.crop.r, solved.crop.r)
827	        && px(got.crop.b, solved.crop.b)
828	        && px(got.corner_radius, solved.corner_radius)
829	        && ratio(got.scale, solved.scale)
830	        && ratio(got.opacity, solved.opacity)
831	}
