833	/// The centre of the camera's crop, from the uncropped source's centre, y
834	/// down: `layout.rs`'s `focus` as the crop shows it (clamped inside the
835	/// source, so not always the focus the switch was given).
836	pub(crate) fn focus_of(camera: &Placement) -> (f64, f64) {
837	    let crop = camera.crop;
838	    ((crop.l - crop.r) / 2.0, (crop.t - crop.b) / 2.0)
839	}
