841	/// Whether two sources show the same thing: the same kind, and the same
842	/// media (a media, still or image source) or the same nest. `in`, `at` and
843	/// `reversed` are not compared, so a split half is the same source.
844	pub(crate) fn same_source(a: &Source, b: &Source) -> bool {
845	    match (a, b) {
846	        (Source::Media { media: x, .. }, Source::Media { media: y, .. })
847	        | (Source::Still { media: x, .. }, Source::Still { media: y, .. })
848	        | (Source::Image { media: x }, Source::Image { media: y }) => x == y,
849	        (Source::Nest { project: x }, Source::Nest { project: y }) => x == y,
850	        _ => false,
851	    }
852	}
