854	/// The candidates in their order (the module doc).
855	fn candidates(focus: (f64, f64), with_screen: bool) -> Vec<LayoutChoice> {
856	    let choice = |layout, shape, corner| LayoutChoice {
857	        layout,
858	        shape,
859	        corner,
860	        focus,
861	    };
862	    let mut all = Vec::new();
863	    for shape in [
864	        LayoutShape::Square,
865	        LayoutShape::Rounded,
866	        LayoutShape::Circle,
867	    ] {
868	        for corner in [
869	            LayoutCorner::BottomRight,
870	            LayoutCorner::BottomLeft,
871	            LayoutCorner::TopRight,
872	            LayoutCorner::TopLeft,
873	        ] {
874	            all.push(choice(CameraLayout::Corner, shape, corner));
875	        }
876	    }
877	    let rest = [
878	        CameraLayout::SideBySide,
879	        CameraLayout::Stacked,
880	        CameraLayout::CameraFull,
881	        CameraLayout::ScreenOnly,
882	    ];
883	    for layout in rest {
884	        if with_screen || !matches!(layout, CameraLayout::SideBySide | CameraLayout::Stacked) {
885	            all.push(choice(
886	                layout,
887	                LayoutShape::default(),
888	                LayoutCorner::default(),
889	            ));
890	        }
891	    }
892	    all
893	}
