895	/// The layout a switch made on `authored`'s canvas (only its `canvas` is
896	/// read): `camera` the camera's end and its source size, `screen` the
897	/// screen's end and source size when the switch has one. `Err(Camera)` when
898	/// no candidate gives the camera end; `Err(Screen)` when some do but none
899	/// also gives the screen end.
900	pub(crate) fn recognise(
901	    authored: &Project,
902	    camera: &Placement,
903	    camera_source: (f64, f64),
904	    screen: Option<(&Placement, (f64, f64))>,
905	) -> Result<LayoutChoice, RoleKind> {
906	    let screen_size = screen.map(|(_, size)| size);
907	    let mut camera_matched = false;
908	    for choice in candidates(focus_of(camera), screen.is_some()) {
909	        let solved = camera_placement(authored, &choice, camera_source, screen_size, camera);
910	        if !alike(camera, &solved) {
911	            continue;
912	        }
913	        camera_matched = true;
914	        let screen_fits = screen
915	            .is_none_or(|(end, size)| alike(end, &screen_placement(authored, choice.layout, size)));
916	        if screen_fits {
917	            return Ok(choice);
918	        }
919	    }
920	    Err(if camera_matched {
921	        RoleKind::Screen
922	    } else {
923	        RoleKind::Camera
924	    })
925	}
926	//! A framing composed into a clip that already moves (road map
927	//! "creator-jobs" VR2b1, spec §11 VR-27): `reframe.rs`'s path F written as
928	//! the clip's base and actions AROUND the actions it already carries, and
929	//! `replace`'s strip. Pure; `edit_reframe.rs`'s op decides and finishes.
930	//!
931	//! **Composition** (VR-27 (b)). P(t) is the input clip's evaluated
932	//! placement and F′ the scheduled path; a key `(k, dx, dy)` composes as
933	//! `scale′ = k·s`, `x′ = k·x + dx`, `y′ = k·y + dy`, raw. The base becomes
934	//! F′(0)∘P(0); an action end writes `video.{scale,x,y}` = F′(end)∘P(end)
935	//! when it names any of them (`null` included) or F′ changes across it.
936	//!
937	//! **Cuts first** (VR-27 (d)). A cut piece `[c − frame, c]` meeting an
938	//! action A naming `speed`, or ending past the clip, is CARRIED by A; any
939	//! other A is split at `c − frame` and `c`, each clamped into A, as
940	//! `edit_split.rs` narrows a straddled action (`state_patch`, `narrow_to`):
941	//! the head keeps A's id and curve, the cut piece is `linear`, the tail
942	//! keeps A's end and curve. So a linear A plays unchanged on every key,
943	//! volume included; an eased one is re-eased on each side (counted).
944	//!
945	//! **Then the moves** (VR-27 (c)), against the pieces: a move in no busy
946	//! span is its own action; one that overlaps a span is shifted earlier to
947	//! end at its start, by at most [`SHIFT_MAX`] and never before the
948	//! previous key or span; otherwise the first span's action CARRIES it — F′
949	//! holds to A's start and reaches the move's value at A's end along A's
950	//! curve, later moves inside A chaining into it.
951	//!
952	//! **Ids** (VR-27 (e)) are minted in time order for every new action and
953	//! tail; a clip's actions are written in start order. With no actions this
954	//! is VR2a2's writing to the byte: key 0 the base, one action per change.
955	
