136	    pub fn reframe_clip(&self, r: &Reframe) -> Result<Outcome, String> {
137	        let clip = self.require_clip(r.clip)?.clone();
138	        if let Some(z) = r
139	            .zoom
140	            .filter(|z| !(z.is_finite() && (1.0..=4.0).contains(z)))
141	        {
142	            return Err(format!("zoom must be between 1 and 4 times fill, not {z}"));
143	        }
144	        for (key, value) in [("from_width", r.from_width), ("from_height", r.from_height)] {
145	            if value == Some(0) {
146	                return Err(format!("{key} must be greater than 0, not 0"));
147	            }
148	        }
149	        if let Some(track) = r.backdrop {
150	            self.require_track(track)?;
151	        }
152	        if r.follow == FramingFollow::Speaker {
153	            for &mic in r.mics.iter().flatten() {
154	                self.require_clip(mic)?;
155	            }
156	        }
157	        match self.refusal(&clip, r) {
158	            Some(why) => Ok(Outcome::Refused(why)),
159	            None => self.reframed(&clip, r),
160	        }
161	    }
