724	/// The samples and shots in clip time (VR-20): kept when in the played
725	/// window, ascending, one sample per clip tick (the earliest media tick's),
726	/// one shot per tick, a cut at 0 or at or past the end dropped.
727	pub(crate) fn in_clip_time(
728	    clip: &Clip,
729	    project: &Project,
730	    subjects: &Subjects,
731	) -> (Vec<SubjectSample>, Vec<Ticks>) {
732	    let Source::Media { media, .. } = clip.source else {
733	        return (Vec::new(), Vec::new());
734	    };
735	    let Some(media) = project.media(media) else {
736	        return (Vec::new(), Vec::new());
737	    };
738	    let at = |t: Ticks| {
739	        in_played_window(clip, media, t)
740	            .then(|| clip_time_of_source(clip, media, t, Round::Down))
741	            .flatten()
742	    };
743	    let mut samples: Vec<(Ticks, Ticks, &SubjectSample)> = subjects
744	        .samples
745	        .iter()
746	        .filter_map(|s| at(s.t).map(|c| (c, s.t, s)))
747	        .collect();
748	    samples.sort_by_key(|&(c, m, _)| (c, m));
749	    samples.dedup_by_key(|&mut (c, _, _)| c);
750	    // A shot rounds UP (VR-24 (a)): its clip tick is the first that shows
751	    // the new shot, where a sample's rounds down.
752	    let at_up = |t: Ticks| {
753	        in_played_window(clip, media, t)
754	            .then(|| clip_time_of_source(clip, media, t, Round::Up))
755	            .flatten()
756	    };
757	    let mut shots: Vec<Ticks> = subjects
758	        .shots
759	        .iter()
760	        .filter_map(|&t| at_up(t))
761	        .filter(|&c| c > 0 && c < clip.duration)
762	        .collect();
763	    shots.sort_unstable();
764	    shots.dedup();
765	    let samples = samples
766	        .into_iter()
767	        .map(|(c, _, s)| SubjectSample { t: c, ..s.clone() })
768	        .collect();
769	    (samples, shots)
770	}
