847	//! A framing written as an edit (road map "creator-jobs" VR2a2 and VR2b1,
848	//! spec §11 VR-25…VR-27): `keep`'s rescale and the blurred backdrop behind
849	//! a `fit` span; the path itself is composed into the clip by
850	//! `reframe_compose.rs`. Pure: each answers a new project and
851	//! `edit_reframe.rs`'s op decides, checks and finishes.
852	//!
853	//! **`keep`** (VR-26, VR-27 (h)) is `set_canvas`'s rescale rule on the
854	//! clip's base and on every end key among `x`, `y` and `scale` that the end
855	//! names, through `rescale_video` itself.
856	//!
857	//! **The backdrop** (VR-25) is ONE copy of the original clip by
858	//! `add_blurred_background`'s builder, spanning the whole clip, because the
859	//! eases into and out of `fit` need it as much as the span itself. It goes
860	//! on the named track when that track can take it — unlocked, not a matte,
861	//! no clip intersecting the clip's span (touching is allowed) — and on a new
862	//! back-most track otherwise, so the op never refuses for a busy track. It
863	//! keeps the original's actions that name `speed`, each end narrowed to
864	//! `speed`, so a ramped clip's copy reads the same frames (VR-27 (i)).
865	
866	use serde_json::{Map, Value};
867	
868	use crate::edit_canvas::rescale_video;
869	use crate::model::{Action, Clip, Project, VideoProps};
870	
871	impl Project {
872	    /// `keep` (VR-26, VR-27 (h)): `set_canvas`'s rescale rule on the clip's
873	    /// base and on each `x`, `y` and `scale` an action's end names, from a
874	    /// `from` canvas to the current one.
875	    pub(crate) fn kept(&self, clip: u32, from: (u32, u32)) -> Project {
876	        let mut next = self.clone();
877	        let (w, h) = (
878	            f64::from(next.canvas.width) / f64::from(from.0),
879	            f64::from(next.canvas.height) / f64::from(from.1),
880	        );
881	        let Some(target) = next.clips.iter_mut().find(|c| c.id == clip) else {
882	            return next;
883	        };
884	        if !(w.is_finite() && h.is_finite()) {
885	            return next;
886	        }
887	        if let Some(video) = target.video.as_mut() {
888	            rescale_video(video, w, h);
889	        }
890	        for action in &mut target.actions {
891	            let Some(Value::Object(end)) = action.end.get_mut("video") else {
892	                continue;
893	            };
894	            let read = |key: &str| end.get(key).and_then(Value::as_f64);
895	            let mut video = VideoProps::default();
896	            video.scale = read("scale").unwrap_or(video.scale);
897	            video.x = read("x").unwrap_or(video.x);
898	            video.y = read("y").unwrap_or(video.y);
899	            rescale_video(&mut video, w, h);
900	            for (key, value) in [("scale", video.scale), ("x", video.x), ("y", video.y)] {
901	                if end.get(key).is_some_and(Value::is_number) {
902	                    end.insert(key.to_string(), Value::from(value));
903	                }
904	            }
905	        }
906	        next
907	    }
908	
909	    /// The backdrop of VR-25: one blurred copy of `original` on `backdrop`
910	    /// when that track can take it, else on a new back-most track (the
911	    /// module doc), with the original's speed actions (VR-27 (i)), their ids
912	    /// after the copy's. The op has refused a nest and a track not behind
913	    /// the clip's before calling, so the `Err` is `blurred_copy`'s own and
914	    /// not reached in practice.
915	    pub(crate) fn with_backdrop(self, original: &Clip, backdrop: u32) -> Result<Project, String> {
916	        let (start, end) = (original.start, original.start + original.duration);
917	        let free = self
918	            .track(backdrop)
919	            .is_some_and(|t| !t.locked && t.matte.is_none())
920	            && !self
921	                .clips
922	                .iter()
923	                .any(|c| c.track == backdrop && c.start < end && c.start + c.duration > start);
924	        let (mut next, track) = if free {
925	            (self, backdrop)
926	        } else {
927	            self.with_back_track()
928	        };
929	        let id = next.allocate_id();
930	        let mut copy = next.blurred_copy(original, id, track)?;
931	        for a in original.actions.iter() {
932	            let Some(speed) = a.end.get("speed") else {
933	                continue;
934	            };
935	            let mut end = Map::new();
936	            end.insert("speed".to_string(), speed.clone());
937	            copy.actions.push(Action {
938	                id: next.allocate_id(),
939	                end: Value::Object(end),
940	                ..a.clone()
941	            });
942	        }
943	        next.clips.push(copy);
944	        Ok(next)
945	    }
946	}
947	//! `follow: cursor` — a screen recording framed on its recorded pointer
948	//! (road map "creator-jobs" VR5, spec §11 VR-50). Pure; `edit_reframe.rs`'s
949	//! op writes the path as it writes every framing (`reframe_compose.rs`).
950	//!
951	//! **The points.** `subjects.cursor` (`reframe_subjects.rs`), in forward-media
952	//! source ticks, is put into clip time by [`cursor_in_clip_time`]: kept in the
953	//! played window, mapped through `clip_source_time.rs`'s one mapping, one
954	//! point per clip tick with `click` and `typing` OR'ed over the points merged.
955	//!
956	//! **The window** is `reframe.rs`'s `Frame` at the request's zoom from the
957	//! current canvas: a point lands on the source canvas through the placement in
958	//! force (`Frame::point`, VR-27 (a)) and the desired centre is that point
959	//! clamped (`Frame::clamp`) — no headroom, no offset, since a pointer is a
960	//! point and not a head.
961	//!
962	//! **The moves** ([`CURSOR_TUNING`]): the first key on the first point; a
963	//! dead zone ±0.20 of the window's width and ±0.12 of its height around the
964	//! window's target, wider than a face's 0.15 because a pointer wanders where a
965	//! face holds still; a down click outside it ARRIVES — its move ends on the
966	//! click's frame, planned back from it at 0.8 window widths a second (at
967	//! least 0.4 s) and started no earlier than the last move's end; any other
968	//! point outside it starts VR-23's move unless one runs, it is within 0.5 s of
969	//! the last move's end with the pointer still in the window, the move would
970	//! end after a pending arrival's start, or the pointer is typing — a typing
971	//! stretch holds the window, where a click inside one still arrives. No cut,
972	//! no `fit`: `where_empty` and `backdrop` never act on it.
973	
974	use crate::clip_source_time::{clip_time_of_source, in_played_window, Round};
975	use crate::model::{Clip, Curve, MediaKind, Project, Source};
976	use crate::reframe::{
977	    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
978	};
979	use crate::reframe_path::{span, MOVE_MIN, MOVE_SPACING};
980	use crate::reframe_subjects::CursorPoint;
981	use crate::reframe_tracks::Follow;
982	use crate::time::{snap_to_frame, Fps, Ticks, TIMESCALE};
983	
984	/// VR-50 (d): the dead zone ±0.20 of the window's width (a face's is 0.15)
985	/// and ±0.12 of its height, 0.8 window widths a second, no headroom.
986	pub const CURSOR_TUNING: FramingTuning = FramingTuning {
987	    dead_zone_width: 0.20,
988	    dead_zone_height: 0.12,
989	    speed: 0.8,
990	    headroom: 0.0,
991	};
