993	/// VR-50 (a): the points in clip time — kept in the played window, mapped
994	/// with `Round::Down`, sorted by (clip tick, media tick), one per clip tick
995	/// (the earliest media tick's position) with `click` and `typing` OR'ed over
996	/// the points it stands for. Empty for a clip that is not a media clip.
997	pub(crate) fn cursor_in_clip_time(
998	    clip: &Clip,
999	    project: &Project,
1000	    points: &[CursorPoint],
1001	) -> Vec<CursorPoint> {
1002	    let Source::Media { media, .. } = clip.source else {
1003	        return Vec::new();
1004	    };
1005	    let Some(media) = project.media(media) else {
1006	        return Vec::new();
1007	    };
1008	    let mut mapped: Vec<(Ticks, Ticks, CursorPoint)> = points
1009	        .iter()
1010	        .filter(|p| in_played_window(clip, media, p.t))
1011	        .filter_map(|p| clip_time_of_source(clip, media, p.t, Round::Down).map(|c| (c, p.t, *p)))
1012	        .collect();
1013	    mapped.sort_by_key(|&(c, m, _)| (c, m));
1014	    let mut out: Vec<CursorPoint> = Vec::with_capacity(mapped.len());
1015	    for (c, _, p) in mapped {
1016	        match out.last_mut() {
1017	            Some(last) if last.t == c => {
1018	                last.click |= p.click;
1019	                last.typing |= p.typing;
1020	            }
1021	            _ => out.push(CursorPoint { t: c, ..p }),
1022	        }
1023	    }
1024	    out
1025	}
