1027	/// The cursor's framing path (spec §11 VR-50). `None` for: no such clip, not
1028	/// a media clip of a video media, a base rotation other than 0, a media with
1029	/// no size, a crop or scale that leaves no picture, or a zoom outside 1…4 —
1030	/// each refused by name before `reframe_clip` calls it. With no point in the
1031	/// played window the path is one key on the picture's centre, which the op
1032	/// refuses as "no subjects".
1033	pub fn plan_cursor_framing(
1034	    project: &Project,
1035	    clip: u32,
1036	    points: &[CursorPoint],
1037	    zoom: f64,
1038	) -> Option<FramingPath> {
1039	    let clip = project.clip(clip)?;
1040	    let Source::Media { media, .. } = clip.source else {
1041	        return None;
1042	    };
1043	    let media = project.media(media)?;
1044	    if media.kind != MediaKind::Video || !media.has_video {
1045	        return None;
1046	    }
1047	    let request = FramingRequest {
1048	        follow: Follow::Subject,
1049	        zoom,
1050	        from_width: project.canvas.width,
1051	        from_height: project.canvas.height,
1052	        where_empty: WhereEmpty::Fit,
1053	    };
1054	    let mut frame = Frame::of(project, clip, &request)?;
1055	    let points = cursor_in_clip_time(clip, project, points);
1056	    if !clip.actions.is_empty() {
1057	        frame.placed = points
1058	            .iter()
1059	            .map(|p| {
1060	                let v = project.evaluate_clip(clip, p.t).video;
1061	                (p.t, v.scale, v.x, v.y)
1062	            })
1063	            .collect();
1064	    }
1065	    Some(write_cursor_keys(
1066	        &frame,
1067	        &points,
1068	        clip.duration,
1069	        project.canvas.fps,
1070	        &CURSOR_TUNING,
1071	    ))
1072	}
