1074	/// The keys (VR-50 (c)–(g)).
1075	fn write_cursor_keys(
1076	    frame: &Frame,
1077	    points: &[CursorPoint],
1078	    duration: Ticks,
1079	    fps: Fps,
1080	    tuning: &FramingTuning,
1081	) -> FramingPath {
1082	    let (ww, wh) = frame.window;
1083	    let raw: Vec<Point> = points.iter().map(|p| frame.point(p.t, p.x, p.y)).collect();
1084	    let desired: Vec<Point> = raw.iter().map(|&p| frame.clamp(p)).collect();
1085	    let mut target = desired.first().copied().unwrap_or_else(|| frame.centre());
1086	    let mut keys = vec![frame.key(0, target, Curve::Linear)];
1087	    let mut last_end: Option<Ticks> = None;
1088	    // A click whose arrival was dropped, or that is already reached, is
1089	    // followed as any other point.
1090	    let mut handled = 0usize;
1091	    let outside = |target: Point, to: Point| {
1092	        (to.0 - target.0).abs() > tuning.dead_zone_width * ww
1093	            || (to.1 - target.1).abs() > tuning.dead_zone_height * wh
1094	    };
1095	    let seconds = |target: Point, to: Point| {
1096	        MOVE_MIN.max((to.0 - target.0).hypot(to.1 - target.1) / (tuning.speed * ww))
1097	    };
1098	    let go = |keys: &mut Vec<FramingKey>, start: Ticks, end: Ticks, from: Point, to: Point| {
1099	        if start > keys.last().expect("the first key").t {
1100	            keys.push(frame.key(start, from, Curve::Linear));
1101	        }
1102	        keys.push(frame.key(end, to, Curve::EaseInOut));
1103	    };
1104	    for (i, p) in points.iter().enumerate() {
1105	        let t = p.t;
1106	        let running = last_end.is_some_and(|end| t < end);
1107	        // The next click from here whose arrival is still to be made, and
1108	        // its planned start (VR-50 (e)).
1109	        let next_click = (i.max(handled)..points.len()).find(|&j| points[j].click);
1110	        let mut pending: Option<Ticks> = None;
1111	        if let Some(j) = next_click.filter(|&j| outside(target, desired[j])) {
1112	            let end = snap_to_frame(points[j].t, fps);
1113	            let length = (seconds(target, desired[j]) * TIMESCALE as f64).round() as Ticks;
1114	            let planned = end.saturating_sub(length).max(last_end.unwrap_or(0));
1115	            if end <= duration && !running && t >= planned {
1116	                let start = snap_to_frame(t, fps);
1117	                if start < end {
1118	                    go(&mut keys, start, end, target, desired[j]);
1119	                    target = desired[j];
1120	                    last_end = Some(end);
1121	                    handled = j + 1;
1122	                    continue;
1123	                }
1124	                // Cannot last a frame: dropped; the click is any point.
1125	                handled = j + 1;
1126	            } else if end <= duration {
1127	                pending = Some(planned);
1128	            } else {
1129	                handled = j + 1;
1130	            }
1131	        }
1132	        if i >= handled && p.click {
1133	            handled = i + 1;
1134	        }
1135	        // VR-50 (f): any other point.
1136	        if running || p.typing || !outside(target, desired[i]) {
1137	            continue;
1138	        }
1139	        let in_window =
1140	            (raw[i].0 - target.0).abs() <= ww / 2.0 && (raw[i].1 - target.1).abs() <= wh / 2.0;
1141	        if last_end.is_some_and(|end| t < end + MOVE_SPACING) && in_window {
1142	            continue;
1143	        }
1144	        let Some((start, end)) = span(t, seconds(target, desired[i]), duration, fps) else {
1145	            continue;
1146	        };
1147	        if pending.is_some_and(|planned| end > planned) {
1148	            continue;
1149	        }
1150	        go(&mut keys, start, end, target, desired[i]);
1151	        target = desired[i];
1152	        last_end = Some(end);
1153	    }
1154	    FramingPath {
1155	        keys,
1156	        shows_fit: false,
1157	        cuts: Vec::new(),
1158	    }
1159	}
