610	    /// `follow: layout` on `clip`, authored on a `from` canvas (the module
611	    /// doc).
612	    pub(crate) fn relaid(&self, clip: u32, from: (u32, u32)) -> Result<Outcome, String> {
613	        let given = self.require_clip(clip)?;
614	        if !given.actions.iter().any(is_layout) {
615	            return Ok(Outcome::Refused(format!(
616	                "clip {clip} holds no camera layout to re-lay; frame it with subject, center, fit \
617	                 or keep"
618	            )));
619	        }
620	        // Pairing over every laid-out clip, then the closure from `clip`.
621	        let edges: Vec<(Act, Act)> = self
622	            .clips
623	            .iter()
624	            .flat_map(|c| layout_acts(c).into_iter().map(move |act| (c, act)))
625	            .filter_map(|(c, act)| Some((act, self.paired(c, act.at)?)))
626	            .collect();
627	        let mut group: BTreeSet<u32> = BTreeSet::from([clip]);
628	        loop {
629	            let before = group.len();
630	            for (a, b) in &edges {
631	                if group.contains(&a.clip) || group.contains(&b.clip) {
632	                    group.insert(a.clip);
633	                    group.insert(b.clip);
634	                }
635	            }
636	            if group.len() == before {
637	                break;
638	            }
639	        }
640	        let clips: Vec<&Clip> = group.iter().filter_map(|id| self.clip(*id)).collect();
641	        let screens: HashMap<u32, bool> = clips.iter().map(|c| (c.id, self.is_screen(c))).collect();
642	
643	        // A clip both a camera and a screen.
644	        if let Some(both) = clips
645	            .iter()
646	            .find(|c| screens[&c.id] && edges.iter().any(|(a, _)| a.clip == c.id))
647	        {
648	            return Ok(Outcome::Refused(format!(
649	                "clip {} is laid out both as a camera and as a screen, so its layouts cannot be \
650	                 re-laid; keep its clips as placed",
651	                both.id
652	            )));
653	        }
654	        // A screen action with no camera switch in front of it.
655	        let unpaired = clips
656	            .iter()
657	            .filter(|c| screens[&c.id])
658	            .flat_map(|c| layout_acts(c))
659	            .filter(|act| !edges.iter().any(|(_, s)| s == act))
660	            .min_by_key(|act| (act.at, act.clip, act.action));
661	        if let Some(act) = unpaired {
662	            return Ok(Outcome::Refused(format!(
663	                "clip {}'s layout action {} at {} has no camera switch in front of it, so it \
664	                 cannot be re-laid; keep its clips as placed",
665	                act.clip,
666	                act.action,
667	                self.layout_timecode(act.at)
668	            )));
669	        }
670	
671	        // Each switch recognised on the authored canvas, in time order.
672	        let mut authored = self.clone();
673	        authored.canvas.width = from.0;
674	        authored.canvas.height = from.1;
675	        let mut acts: Vec<Act> = clips
676	            .iter()
677	            .filter(|c| !screens[&c.id])
678	            .flat_map(|c| layout_acts(c))
679	            .collect();
680	        acts.sort_by_key(|act| (act.at, act.clip, act.action));
681	        let mut switches: Vec<Switch> = Vec::new();
682	        for camera in acts {
683	            let screen = edges.iter().find(|(a, _)| *a == camera).map(|(_, s)| *s);
684	            let found = match (self.end_of(&camera), screen.map(|s| self.end_of(&s))) {
685	                (None, _) => Err(RoleKind::Camera),
686	                (Some(_), Some(None)) => Err(RoleKind::Screen),
687	                (Some(cam), shown) => {
688	                    let shown = shown.flatten();
689	                    let shown = shown.as_ref().map(|(end, size)| (end, *size));
690	                    recognise(&authored, &cam.0, cam.1, shown)
691	                }
692	            };
693	            let choice = match found {
694	                Ok(choice) => choice,
695	                Err(kind) => {
696	                    let named = screen.filter(|_| kind == RoleKind::Screen);
697	                    return Ok(self.unrecognised(&named.unwrap_or(camera), from));
698	                }
699	            };
700	            switches.push(Switch {
701	                camera,
702	                screen,
703	                choice,
704	                camera_pieces: self.pieces(&camera),
705	                screen_pieces: screen.map_or_else(Vec::new, |s| self.pieces(&s)),
706	            });
707	        }
708	
709	        // The members: the group's clips and every switch's pieces.
710	        let mut members: BTreeSet<u32> = group.clone();
711	        for s in &switches {
712	            members.extend(s.camera_pieces.iter().chain(&s.screen_pieces));
713	        }
714	        let (w, h) = (
715	            f64::from(self.canvas.width) / f64::from(from.0),
716	            f64::from(self.canvas.height) / f64::from(from.1),
717	        );
718	        let mut next = self.clone();
719	        for c in next.clips.iter_mut().filter(|c| members.contains(&c.id)) {
720	            if let Some(video) = c.video.as_mut() {
721	                rescale_video(video, w, h);
722	            }
723	            if group.contains(&c.id) {
724	                c.actions.retain(|a| !is_layout(a));
725	            }
726	        }
727	
728	        // The replay, in time order.
729	        let tall = self.canvas.height > self.canvas.width;
730	        for s in &switches {
731	            let mut choice = s.choice;
732	            if tall && choice.layout == CameraLayout::SideBySide {
733	                choice.layout = CameraLayout::Stacked;
734	            }
735	            let timed: Vec<(&Clip, &Action)> = std::iter::once(s.camera)
736	                .chain(s.screen)
737	                .filter_map(|act| self.action_of(&act))
738	                .collect();
739	            let (duration, curve) = switch_timing(&timed);
740	            let outcome = {
741	                let role = |kind: RoleKind, act: &Act, pieces: &[u32]| -> Option<Role<'_>> {
742	                    Some(Role {
743	                        kind,
744	                        clip: next.clip(act.clip)?,
745	                        at: act.at,
746	                        later: pieces.iter().filter_map(|id| next.clip(*id)).collect(),
747	                        ender: None,
748	                    })
749	                };
750	                let mut roles = Vec::new();
751	                roles.extend(role(RoleKind::Camera, &s.camera, &s.camera_pieces));
752	                if let Some(screen) = &s.screen {
753	                    roles.extend(role(RoleKind::Screen, screen, &s.screen_pieces));
754	                }
755	                next.compose_switch(&choice, &roles, s.camera.at, duration, curve)
756	            };
757	            match outcome? {
758	                Outcome::Applied(applied) => next = applied,
759	                Outcome::Identity => {}
760	                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
761	            }
762	        }
763	
764	        // The other moving ends, re-based.
765	        for id in &members {
766	            let (Some(old), Some(new)) = (self.clip(*id), next.clip(*id)) else {
767	                continue;
768	            };
769	            let bases: Vec<(usize, Placement, Placement)> = new
770	                .actions
771	                .iter()
772	                .enumerate()
773	                .filter(|(_, a)| moves(a) && !is_layout(a))
774	                .map(|(i, a)| (i, in_effect(old, a.start), in_effect(new, a.start)))
775	                .collect();
776	            let Some(target) = next.clips.iter_mut().find(|c| c.id == *id) else {
777	                continue;
778	            };
779	            for (i, was, now) in bases {
780	                if let Some(Value::Object(end)) = target.actions[i].end.get_mut("video") {
781	                    conjugate(end, &was, &now);
782	                }
783	            }
784	        }
785	        self.finish(next)
786	    }
787	}
788	//! A camera layout recognised from the placements it wrote (road map
789	//! "creator-jobs" VR5b, spec §11 VR-53 (b)): the layout, shape and corner
790	//! whose solve on the AUTHORED canvas gives a switch's camera end and its
791	//! screen end. Pure; beside `layout.rs`, which is at its 400-line cap, and
792	//! read only by `reframe_layout.rs`.
793	//!
794	//! The candidates are tried in a fixed order — `corner` with each shape
795	//! (square, rounded, circle) at each corner (bottom right, bottom left, top
796	//! right, top left), `side_by_side`, `stacked` (both skipped when the switch
797	//! has no screen), `camera_full`, `screen_only` — and the first whose camera
798	//! AND screen placements are [`alike`] the ends wins. A candidate is solved
799	//! with the camera end's own crop centre as its `focus` ([`focus_of`]), so a
800	//! crop centred on a person (CO-70) is recognised whatever the focus was;
801	//! the tolerance is `RECOGNISE_PX` in every pixel-valued key (a switch's
802	//! `x` and `y` are whole pixels, its crop and radius are not) and
803	//! `RECOGNISE_RATIO` in scale and opacity, so an end moved by hand by more
804	//! than a pixel is not a layout Frame Job made.
805	
806	use crate::edit_layout_reach::RoleKind;
807	use crate::layout::{
808	    camera_placement, screen_placement, CameraLayout, LayoutChoice, LayoutCorner, LayoutShape,
809	    Placement,
810	};
