895	/// The layout a switch made on `authored`'s canvas (only its `canvas` is
896	/// read): `camera` the camera's end and its source size, `screen` the
897	/// screen's end and source size when the switch has one. `Err(Camera)` when
898	/// no candidate gives the camera end; `Err(Screen)` when some do but none
899	/// also gives the screen end.
900	pub(crate) fn recognise(
901	    authored: &Project,
902	    camera: &Placement,
903	    camera_source: (f64, f64),
904	    screen: Option<(&Placement, (f64, f64))>,
905	) -> Result<LayoutChoice, RoleKind> {
906	    let screen_size = screen.map(|(_, size)| size);
907	    let mut camera_matched = false;
908	    for choice in candidates(focus_of(camera), screen.is_some()) {
909	        let solved = camera_placement(authored, &choice, camera_source, screen_size, camera);
910	        if !alike(camera, &solved) {
911	            continue;
912	        }
913	        camera_matched = true;
914	        let screen_fits = screen
915	            .is_none_or(|(end, size)| alike(end, &screen_placement(authored, choice.layout, size)));
916	        if screen_fits {
917	            return Ok(choice);
918	        }
919	    }
920	    Err(if camera_matched {
921	        RoleKind::Screen
922	    } else {
923	        RoleKind::Camera
924	    })
925	}
